static_assert(std::is_base_of_v<DispatcherObject, DependencyObject>);
static_assert(std::is_base_of_v<DependencyObject, Visual>);
static_assert(std::is_base_of_v<Visual, UIElement>);
static_assert(std::is_base_of_v<UIElement, FrameworkElement>);
static_assert(std::is_base_of_v<FrameworkElement, Control>);
static_assert(std::is_base_of_v<ListBoxItem, ComboBoxItem>);
static_assert(std::is_base_of_v<Control, Button>);
static_assert(!std::is_copy_constructible_v<RoutedEventArgs>);
static_assert(!std::is_copy_constructible_v<MouseEventArgs>);
static_assert(!std::is_copy_constructible_v<KeyEventArgs>);
static_assert(!std::is_copy_constructible_v<TextCompositionEventArgs>);
static_assert(std::is_move_constructible_v<MouseEventArgs>);
static_assert(std::is_move_constructible_v<KeyEventArgs>);
static_assert(std::is_move_constructible_v<TextCompositionEventArgs>);
