	ScrollViewer* InstallItemsScrollTemplate(ItemsControl& items)
	{
		auto root = MakeTestControl<ScrollViewer>(0, 0, 0, 0);
		root->Width = cui::layout::Length::Auto();
		root->Height = cui::layout::Length::Auto();
		root->HorizontalAlignment = HorizontalAlignment::Stretch;
		root->VerticalAlignment = VerticalAlignment::Stretch;
		cui::framework::XamlAccess::SetTemplatedParent(*root, &items);
		auto presenter = MakeTestControl<ItemsPresenter>();
		auto* presenterPointer = presenter.get();
		cui::framework::XamlAccess::SetTemplatedParent(*presenterPointer, &items);
		auto* scroll = root.get();
		root->AddOwned(std::move(presenter));
		cui::framework::TemplateAccess::SetTemplateRoot(
			items, std::move(root));
		if (!cui::framework::TemplateAccess::RegisterItemsPresenter(
			items, presenterPointer))
			throw std::logic_error("failed to install ItemsPresenter");
		return scroll;
	}

	Control* GetGeneratedPresentation(Control* container)
	{
		if (auto* presenter = dynamic_cast<ContentPresenter*>(container))
			return presenter->GetGeneratedContent();
		if (auto* item = dynamic_cast<ItemContainerControl*>(container))
			return item->Content();
		return container;
	}

	template<typename TControl>
	TControl* GetGeneratedPresentationAs(Control* container)
	{
		return dynamic_cast<TControl*>(GetGeneratedPresentation(container));
	}

	InputReport PointerInput(
		InputReportKind kind,
		MouseButton changedButton,
		int x,
		int y,
		MouseButton pressedButton = MouseButton::None,
		ModifierKeys modifiers = ModifierKeys::None)
	{
		InputReport input;
		input.Kind = kind;
		input.X = x;
		input.Y = y;
		input.ChangedButton = changedButton;
		input.ButtonStates = MouseButtonStates::WithPressed(pressedButton);
		input.Modifiers = modifiers;
		input.ClickCount = kind == InputReportKind::PointerDoubleClick ? 2
			: kind == InputReportKind::PointerDown ? 1 : 0;
		return input;
	}

	InputReport WheelInput(
		int delta,
		int x,
		int y,
		ModifierKeys modifiers = ModifierKeys::None,
		bool horizontal = false)
	{
		InputReport input;
		input.Kind = horizontal ? InputReportKind::HorizontalMouseWheel
			: InputReportKind::MouseWheel;
		input.X = x;
		input.Y = y;
		input.WheelDelta = delta;
		input.Modifiers = modifiers;
		return input;
	}

	InputReport KeyInput(
		InputReportKind kind,
		Key key,
		ModifierKeys modifiers = ModifierKeys::None)
	{
		InputReport input;
		input.Kind = kind;
		input.Key = key;
		input.Modifiers = modifiers;
		return input;
	}

	InputReport LifecycleInput(InputReportKind kind, int x = 0, int y = 0)
	{
		InputReport input;
		input.Kind = kind;
		input.X = x;
		input.Y = y;
		return input;
	}

