	runner.Add("Virtualized TreeView item lookup stays coherent at scale", []
	{
		constexpr size_t treeNodeCount = 5000;
		TreeView tree; ConfigureTestControl(tree, 0, 0, 240, 140);
		auto treePanel = std::make_shared<ItemsPanelTemplate>();
		treePanel->Kind = ItemsPanelKind::VirtualizingStack;
		treePanel->ItemHeight = 28.0f;
		treePanel->CacheLength = 0.0f;
		tree.SetItemsPanel(ItemsPanelTemplateReference(treePanel));
		auto* treeScroll = InstallItemsScrollTemplate(tree);
		auto treeItems = std::make_shared<ObservableBindingList>(L"TreeEntry");
		std::shared_ptr<ObservableObject> lastTreeRecord;
		{
			auto update = treeItems->Items.DeferNotifications();
			treeItems->Items.reserve(treeNodeCount);
			for (size_t index = 0; index < treeNodeCount; ++index)
			{
				auto item = std::make_shared<ObservableObject>();
				CUI_EXPECT_TRUE(item->DefineProperty(
					L"Name", L"Node " + std::to_wstring(index)));
				if (index + 1 == treeNodeCount) lastTreeRecord = item;
				treeItems->Items.push_back(BindingSourceReference(item));
			}
		}
		tree.SetDisplayMemberPath(L"Name");
		tree.SetItemsSource(BindingListReference(treeItems));
		tree.Arrange(cui::core::Rect{ 0.0f, 0.0f, 240.0f, 140.0f });
		tree.UpdateLayout();
		CUI_EXPECT_EQ(treeNodeCount, tree.ItemCount());
		CUI_EXPECT_TRUE(tree.IsVirtualizing());
		CUI_EXPECT_TRUE(tree.GeneratedItemCount() < 16ULL);
		CUI_EXPECT_TRUE(tree.ContainerFromIndex(0) != nullptr);
		CUI_EXPECT_TRUE(tree.ContainerFromIndex(treeNodeCount - 1) == nullptr);
		CUI_EXPECT_TRUE(treeItems->Items.Move(treeNodeCount - 1, 0));
		CUI_EXPECT_TRUE(treeScroll->VerticalOffset > 0.0);
		treeScroll->ScrollToHome();
		tree.UpdateLayout();
		auto* movedTreeContainer = tree.ContainerFromIndex(0);
		CUI_EXPECT_TRUE(movedTreeContainer != nullptr);
		CUI_EXPECT_TRUE(movedTreeContainer
			&& movedTreeContainer->GetDataContext().Get() == lastTreeRecord.get());
		auto* movedTreeHeader = movedTreeContainer
			? movedTreeContainer->GetHeaderVisual() : nullptr;
		const auto movedBounds = movedTreeHeader
			? movedTreeHeader->GetAbsoluteBoundsDip()
			: movedTreeContainer->GetAbsoluteBoundsDip();
		const auto treeBounds = tree.GetAbsoluteBoundsDip();
		auto* movedTreeHit = tree.HitTestItem(
			(movedBounds.left + movedBounds.right) * 0.5f - treeBounds.left,
			(movedBounds.top + movedBounds.bottom) * 0.5f - treeBounds.top);
		CUI_EXPECT_TRUE(movedTreeHit == movedTreeContainer);
		treeItems->Items.erase(treeItems->Items.begin());
		CUI_EXPECT_EQ(treeNodeCount - 1, tree.ItemCount());
		CUI_EXPECT_TRUE(tree.ContainerFromIndex(0) != movedTreeContainer);
	});

