	runner.Add("ItemContainerGenerator preserves identity across precise changes", []
	{
		auto makeRecord = [](const std::wstring& name)
		{
			auto record = std::make_shared<ObservableObject>();
			CUI_EXPECT_TRUE(record->DefineProperty(L"Name", name));
			return BindingSourceReference(record);
		};
		auto records = std::make_shared<ObservableBindingList>(L"Row");
		for (const auto* name : { L"A", L"B", L"C", L"D" })
			records->Items.push_back(makeRecord(name));

		ListBox box; ConfigureTestControl(box, 0, 0, 180, 160);
		box.SetDisplayMemberPath(L"Name");
		box.SetItemsSource(BindingListReference(records));
		box.Arrange(cui::core::Rect{ 0.0f, 0.0f, 180.0f, 160.0f });
		box.SetSelectedIndex(2);
		auto* cContainer = dynamic_cast<ListBoxItem*>(
			box.GetGeneratedItem(2));
		CUI_EXPECT_TRUE(cContainer != nullptr);

		records->Items.insert(records->Items.begin(), makeRecord(L"Zero"));
		CUI_EXPECT_EQ(5ULL, box.ItemCount());
		CUI_EXPECT_TRUE(box.GetGeneratedItem(3) == cContainer);
		CUI_EXPECT_EQ(3ULL, cContainer->ItemIndex());
		CUI_EXPECT_EQ(3, box.SelectedIndex);

		CUI_EXPECT_TRUE(records->Items.Move(3, 1));
		CUI_EXPECT_TRUE(box.GetGeneratedItem(1) == cContainer);
		CUI_EXPECT_EQ(1ULL, cContainer->ItemIndex());
		CUI_EXPECT_EQ(1, box.SelectedIndex);

		auto* oldSelectedAddress = box.GetGeneratedItem(1);
		CUI_EXPECT_TRUE(records->Items.Replace(1, makeRecord(L"C2")));
		CUI_EXPECT_TRUE(box.GetGeneratedItem(1) != oldSelectedAddress);
		CUI_EXPECT_EQ(1, box.SelectedIndex);
		CUI_EXPECT_EQ(5ULL, box.GeneratedItemCount());
		auto* host = TemplateAccess::GetItemsHost(box);
		CUI_EXPECT_TRUE(host != nullptr);
		CUI_EXPECT_EQ(5ULL, host->GetVisualChildrenView().size());
		for (size_t index = 0; index < box.ItemCount(); ++index)
			CUI_EXPECT_TRUE(host->GetVisualChildrenView()[index]
				== box.GetGeneratedItem(index));

		records->Items.erase(records->Items.begin());
		CUI_EXPECT_EQ(4ULL, box.ItemCount());
		CUI_EXPECT_EQ(0, box.SelectedIndex);
		for (size_t index = 0; index < box.ItemCount(); ++index)
		{
			auto* item = dynamic_cast<ListBoxItem*>(
				box.GetGeneratedItem(index));
			CUI_EXPECT_TRUE(item != nullptr);
			CUI_EXPECT_EQ(index, item->ItemIndex());
		}
		auto* changedAddress = box.GetGeneratedItem(0);
		auto* unrelatedAddress = box.GetGeneratedItem(2);
		CUI_EXPECT_TRUE(records->Items[0].Get()->TrySetValue(
			L"Name", BindingValue(L"C3")));
		// WPF-style ContentPresenter updates the item visual in place; a record
		// property change must not replace its ListBoxItem container identity.
		CUI_EXPECT_TRUE(box.GetGeneratedItem(0) == changedAddress);
		CUI_EXPECT_TRUE(box.GetGeneratedItem(2) == unrelatedAddress);
		auto* refreshed = dynamic_cast<ListBoxItem*>(box.GetGeneratedItem(0));
		auto* refreshedLabel = refreshed
			? dynamic_cast<Label*>(refreshed->Content()) : nullptr;
		CUI_EXPECT_TRUE(refreshedLabel != nullptr);
		CUI_EXPECT_EQ(std::wstring(L"C3"), refreshedLabel->Text);
	});

	runner.Add("ItemsControl rolls back failed live materialization", []
	{
		auto makeRecord = [](const std::wstring& name)
		{
			auto record = std::make_shared<ObservableObject>();
			CUI_EXPECT_TRUE(record->DefineProperty(L"Name", name));
			return BindingSourceReference(record);
		};
		class FailingItemTemplate final : public IItemTemplate
		{
		public:
			const std::wstring& DataTypeName() const noexcept override
			{
				static const std::wstring typeName = L"Row";
				return typeName;
			}
			std::unique_ptr<Control> Build(
				const BindingSourceReference& item,
				size_t,
				std::wstring* outError) const override
			{
				BindingValue value;
				if (!item || !item.Get()->TryGetValue(L"Name", value))
				{
					if (outError) *outError = L"missing Name";
					return {};
				}
				const auto name = value.ToString();
				if (name == L"Reject")
				{
					if (outError) *outError = L"rejected live item";
					return {};
				}
				if (name == L"Throw")
				{
					if (outError) *outError = L"throwing live item";
					throw std::runtime_error(
						"intentional live item materialization failure");
				}
				if (outError) outError->clear();
				return MakeTestControl<Label>(name, 0, 0);
			}
		};

		auto records = std::make_shared<ObservableBindingList>(L"Row");
		records->Items.push_back(makeRecord(L"Alpha"));
		records->Items.push_back(makeRecord(L"Beta"));
		ItemsControl items; ConfigureTestControl(items, 0, 0, 180, 120);
		items.SetItemTemplate(ItemTemplateReference(
			std::make_shared<FailingItemTemplate>()));
		items.SetItemsSource(BindingListReference(records));
		auto* alphaVisual = items.GetGeneratedItem(0);
		auto* betaVisual = items.GetGeneratedItem(1);
		CUI_EXPECT_TRUE(alphaVisual != nullptr);
		CUI_EXPECT_TRUE(betaVisual != nullptr);

		// The precise Add path and its full-rebuild fallback both reject the
		// candidate before touching the committed tree. Since IBindingList is
		// read-only, ItemsControl pins itself to its last materialized snapshot.
		records->Items.push_back(makeRecord(L"Reject"));
		CUI_EXPECT_TRUE(items.GetItemsSource().Shared() != records);
		CUI_EXPECT_EQ(2ULL, items.ItemCount());
		CUI_EXPECT_EQ(2ULL, items.GeneratedItemCount());
		CUI_EXPECT_TRUE(items.GetGeneratedItem(0) == alphaVisual);
		CUI_EXPECT_TRUE(items.GetGeneratedItem(1) == betaVisual);
		CUI_EXPECT_TRUE(items.LastTemplateError().find(L"rejected")
			!= std::wstring::npos);
		BindingSourceReference materialized;
		CUI_EXPECT_TRUE(items.GetItemsSource().Get()->TryGetItem(
			0, materialized));
		CUI_EXPECT_TRUE(materialized.Shared()
			== records->Items[0].Shared());
		records->Items.push_back(makeRecord(L"Ignored"));
		CUI_EXPECT_EQ(2ULL, items.ItemCount());

		// A throwing template follows the same rollback contract and propagates
		// the original failure to the collection mutator.
		auto throwingRecords =
			std::make_shared<ObservableBindingList>(L"Row");
		throwingRecords->Items.push_back(makeRecord(L"One"));
		throwingRecords->Items.push_back(makeRecord(L"Two"));
		ItemsControl throwingItems; ConfigureTestControl(throwingItems, 0, 0, 180, 120);
		throwingItems.SetItemTemplate(ItemTemplateReference(
			std::make_shared<FailingItemTemplate>()));
		throwingItems.SetItemsSource(BindingListReference(throwingRecords));
		bool liveBuildThrew = false;
		try
		{
			throwingRecords->Items.push_back(makeRecord(L"Throw"));
		}
		catch (const std::runtime_error&)
		{
			liveBuildThrew = true;
		}
		CUI_EXPECT_TRUE(liveBuildThrew);
		CUI_EXPECT_TRUE(throwingItems.GetItemsSource().Shared()
			!= throwingRecords);
		CUI_EXPECT_EQ(2ULL, throwingItems.ItemCount());
		CUI_EXPECT_EQ(2ULL, throwingItems.GeneratedItemCount());
		CUI_EXPECT_TRUE(throwingItems.LastTemplateError().find(L"throwing")
			!= std::wstring::npos);
	});

	runner.Add("ItemsControl live snapshot keeps incremental complexity", []
	{
		class CountingBindingList final : public IBindingList
		{
		public:
			size_t Count() const noexcept override { return Items.size(); }
			bool TryGetItem(
				size_t index, BindingSourceReference& out) const override
			{
				++TryGetQueries;
				if (index >= Items.size() || !Items[index]) return false;
				out = Items[index];
				return true;
			}
			EventConnection SubscribeChanged(ChangedHandler handler) override
			{
				if (PublishAddDuringSubscribe)
				{
					PublishAddDuringSubscribe = false;
					const size_t oldSize = Items.size();
					Items.push_back(PendingSubscribedItem);
					handler(CollectionChangedEventArgs{
						CollectionChangeAction::Add,
						CollectionChangedEventArgs::Npos, oldSize,
						0, 1, oldSize, Items.size() });
				}
				return Changed.Subscribe(
					[handler = std::move(handler)](
						CountingBindingList*,
						const CollectionChangedEventArgs& change)
					{ handler(change); });
			}
			const std::wstring& ItemTypeName() const noexcept override
			{
				static const std::wstring typeName = L"Row";
				return typeName;
			}
			void Add(BindingSourceReference item)
			{
				const size_t oldSize = Items.size();
				Items.push_back(std::move(item));
				cui::framework::EventAccess::Raise(
					Changed, this, CollectionChangedEventArgs{
					CollectionChangeAction::Add,
					CollectionChangedEventArgs::Npos, oldSize,
					0, 1, oldSize, Items.size() });
			}

			std::vector<BindingSourceReference> Items;
			BindingSourceReference PendingSubscribedItem;
			bool PublishAddDuringSubscribe = false;
			mutable size_t TryGetQueries = 0;
			Event<void(CountingBindingList*,
				const CollectionChangedEventArgs&)> Changed;
		};
		auto makeRecord = [](int index)
		{
			auto record = std::make_shared<ObservableObject>();
			CUI_EXPECT_TRUE(record->DefineProperty(
				L"Name", L"Row " + std::to_wstring(index)));
			return BindingSourceReference(record);
		};

		auto source = std::make_shared<CountingBindingList>();
		for (int index = 0; index < 256; ++index)
			source->Items.push_back(makeRecord(index));
		ItemsControl items; ConfigureTestControl(items, 0, 0, 180, 120);
		items.SetDisplayMemberPath(L"Name");
		items.SetItemsSource(BindingListReference(source));
		CUI_EXPECT_EQ(256ULL, items.ItemCount());
		source->TryGetQueries = 0;
		source->Add(makeRecord(256));
		CUI_EXPECT_EQ(257ULL, items.ItemCount());
		CUI_EXPECT_EQ(257ULL, items.GeneratedItemCount());
		// Snapshot preparation and visual preparation each read the appended item;
		// neither scans the 256 already-committed records.
		CUI_EXPECT_TRUE(source->TryGetQueries <= 4ULL);

		auto synchronous = std::make_shared<CountingBindingList>();
		synchronous->Items.push_back(makeRecord(1));
		synchronous->PendingSubscribedItem = makeRecord(2);
		synchronous->PublishAddDuringSubscribe = true;
		ItemsControl synchronousItems; ConfigureTestControl(synchronousItems, 0, 0, 180, 120);
		synchronousItems.SetDisplayMemberPath(L"Name");
		synchronousItems.SetItemsSource(BindingListReference(synchronous));
		CUI_EXPECT_EQ(2ULL, synchronousItems.ItemCount());
		CUI_EXPECT_EQ(2ULL, synchronousItems.GeneratedItemCount());
		CUI_EXPECT_TRUE(synchronousItems.GetItemsSource().Shared()
			== synchronous);
	});

	runner.Add("ItemsControl restores snapshot after post-commit callback failure", []
	{
		class ThrowAfterGeneratedItemsControl final : public ItemsControl
		{
		public:
			using ItemsControl::ItemsControl;
			bool ThrowAfterNextIncrementalCommit = false;

		protected:
			void OnGeneratedItemsRebuilt() override
			{
				if (!ThrowAfterNextIncrementalCommit) return;
				ThrowAfterNextIncrementalCommit = false;
				throw std::runtime_error(
					"intentional generated-items callback failure");
			}
		};
		auto makeRecord = [](const std::wstring& name)
		{
			auto record = std::make_shared<ObservableObject>();
			CUI_EXPECT_TRUE(record->DefineProperty(L"Name", name));
			return BindingSourceReference(record);
		};
		auto source = std::make_shared<ObservableBindingList>(L"Row");
		source->Items.push_back(makeRecord(L"A"));
		source->Items.push_back(makeRecord(L"B"));
		ThrowAfterGeneratedItemsControl items;
		ConfigureTestControl(items, 0, 0, 180, 120);
		items.SetDisplayMemberPath(L"Name");
		items.SetItemsSource(BindingListReference(source));
		items.ThrowAfterNextIncrementalCommit = true;
		bool callbackThrew = false;
		try
		{
			source->Items.push_back(makeRecord(L"C"));
		}
		catch (const std::runtime_error&)
		{
			callbackThrew = true;
		}
		CUI_EXPECT_TRUE(callbackThrew);
		CUI_EXPECT_TRUE(items.GetItemsSource().Shared() != source);
		CUI_EXPECT_EQ(2ULL, items.ItemCount());
		CUI_EXPECT_EQ(2ULL, items.GeneratedItemCount());
		CUI_EXPECT_TRUE(items.GetGeneratedItem(0) != nullptr);
		CUI_EXPECT_TRUE(items.GetGeneratedItem(1) != nullptr);
	});

	runner.Add("Virtual generator anchors scroll and remaps realized containers", []
	{
		auto makeRecord = [](int value)
		{
			auto record = std::make_shared<ObservableObject>();
			CUI_EXPECT_TRUE(record->DefineProperty(
				L"Name", L"Row " + std::to_wstring(value)));
			return BindingSourceReference(record);
		};
		auto records = std::make_shared<ObservableBindingList>(L"Row");
		for (int index = 0; index < 1000; ++index)
			records->Items.push_back(makeRecord(index));
		auto panel = std::make_shared<ItemsPanelTemplate>();
		panel->Kind = ItemsPanelKind::VirtualizingStack;
		panel->ItemHeight = 20.0f;
		panel->CacheLength = 0.0f;

		ListBox box; ConfigureTestControl(box, 0, 0, 180, 100);
		box.SetDisplayMemberPath(L"Name");
		box.SetItemsPanel(ItemsPanelTemplateReference(panel));
		auto* scroll = InstallItemsScrollTemplate(box);
		box.SetItemsSource(BindingListReference(records));
		box.Arrange(cui::core::Rect{ 0.0f, 0.0f, 180.0f, 100.0f });
		box.UpdateLayout();
		scroll->ScrollToVerticalOffset(400.0);
		box.SetSelectedIndex(20);
		auto* anchor = dynamic_cast<ListBoxItem*>(box.GetGeneratedItem(20));
		CUI_EXPECT_TRUE(anchor != nullptr);

		records->Items.insert(records->Items.begin(), makeRecord(-1));
		CUI_EXPECT_EQ(420.0, scroll->VerticalOffset);
		CUI_EXPECT_TRUE(box.GetGeneratedItem(21) == anchor);
		CUI_EXPECT_EQ(21ULL, anchor->ItemIndex());
		CUI_EXPECT_EQ(21, box.SelectedIndex);

		CUI_EXPECT_TRUE(records->Items.Move(21, 25));
		CUI_EXPECT_EQ(500.0, scroll->VerticalOffset);
		CUI_EXPECT_TRUE(box.GetGeneratedItem(25) == anchor);
		CUI_EXPECT_EQ(25ULL, anchor->ItemIndex());
		CUI_EXPECT_EQ(25, box.SelectedIndex);

		records->Items.erase(records->Items.begin());
		CUI_EXPECT_EQ(480.0, scroll->VerticalOffset);
		CUI_EXPECT_TRUE(box.GetGeneratedItem(24) == anchor);
		CUI_EXPECT_EQ(24, box.SelectedIndex);

		auto* replacedAddress = box.GetGeneratedItem(24);
		CUI_EXPECT_TRUE(records->Items.Replace(24, makeRecord(2000)));
		CUI_EXPECT_TRUE(box.GetGeneratedItem(24) != replacedAddress);
		CUI_EXPECT_EQ(24, box.SelectedIndex);
		CUI_EXPECT_TRUE(box.GeneratedItemCount() <= 8ULL);
		CUI_EXPECT_TRUE(box.RecycledItemCount() <= 16ULL);

		std::vector<BindingSourceReference> snapshot(
			records->Items.begin(), records->Items.end());
		records->Items.assign(snapshot.begin(), snapshot.end());
		CUI_EXPECT_EQ(1000ULL, box.ItemCount());
		CUI_EXPECT_TRUE(box.GeneratedItemCount() <= 8ULL);
	});

	runner.Add("CollectionViewSource filters sorts and preserves item identity", []
	{
		auto makeRecord = [](const std::wstring& name, int score, bool active)
		{
			auto record = std::make_shared<ObservableObject>();
			CUI_EXPECT_TRUE(record->DefineProperty(L"Name", name));
			CUI_EXPECT_TRUE(record->DefineProperty(L"Score", score));
			CUI_EXPECT_TRUE(record->DefineProperty(L"Active", active));
			return record;
		};
		auto alice = makeRecord(L"Alice", 20, true);
		auto bob = makeRecord(L"Bob", 30, true);
		auto carol = makeRecord(L"Carol", 40, false);
		auto dora = makeRecord(L"Dora", 30, true);
		auto source = std::make_shared<ObservableBindingList>(L"Person");
		for (const auto& record : { alice, bob, carol, dora })
			source->Items.push_back(BindingSourceReference(record));

		auto view = std::make_shared<CollectionViewSource>();
		view->SetFilterDescriptions({ CollectionFilterDescription{
			L"Active", CollectionFilterOperator::Equals, BindingValue(true), false } });
		view->SetSortDescriptions({
			CollectionSortDescription{
				L"Score", CollectionSortDirection::Descending, false },
			CollectionSortDescription{
				L"Name", CollectionSortDirection::Ascending, true } });
		std::vector<CollectionChangeAction> changes;
		auto changed = view->SubscribeChanged(
			[&](const CollectionChangedEventArgs& change)
			{ changes.push_back(change.Action); });
		view->SetSource(BindingListReference(source));
		CUI_EXPECT_EQ(3ULL, view->Count());
		BindingSourceReference item;
		CUI_EXPECT_TRUE(view->TryGetItem(0, item));
		CUI_EXPECT_TRUE(item.Shared() == bob);
		CUI_EXPECT_TRUE(view->TryGetItem(1, item));
		CUI_EXPECT_TRUE(item.Shared() == dora);
		CUI_EXPECT_TRUE(view->TryGetItem(2, item));
		CUI_EXPECT_TRUE(item.Shared() == alice);
		CUI_EXPECT_TRUE(std::none_of(changes.begin(), changes.end(),
			[](auto action) { return action == CollectionChangeAction::Reset; }));

		ListBox box; ConfigureTestControl(box, 0, 0, 180, 120);
		box.SetDisplayMemberPath(L"Name");
		box.SetItemsSource(BindingListReference(view));
		box.SetSelectedIndex(1);
		auto* bobContainer = box.GetGeneratedItem(0);
		auto* doraContainer = box.GetGeneratedItem(1);
		auto* aliceContainer = box.GetGeneratedItem(2);
		CUI_EXPECT_TRUE(view->MoveCurrentToPosition(1));
		CUI_EXPECT_TRUE(view->CurrentItem().Shared() == dora);

		CUI_EXPECT_TRUE(alice->SetValue(L"Score", 50));
		CUI_EXPECT_TRUE(view->TryGetItem(0, item));
		CUI_EXPECT_TRUE(item.Shared() == alice);
		CUI_EXPECT_TRUE(box.GetGeneratedItem(0) == aliceContainer);
		CUI_EXPECT_TRUE(box.GetGeneratedItem(1) == bobContainer);
		CUI_EXPECT_TRUE(box.GetGeneratedItem(2) == doraContainer);
		CUI_EXPECT_EQ(2, box.SelectedIndex);
		CUI_EXPECT_EQ(2, view->CurrentPosition());
		CUI_EXPECT_TRUE(view->CurrentItem().Shared() == dora);

		CUI_EXPECT_TRUE(dora->SetValue(L"Active", false));
		CUI_EXPECT_EQ(2ULL, view->Count());
		CUI_EXPECT_EQ(1, view->CurrentPosition());
		CUI_EXPECT_TRUE(view->CurrentItem().Shared() == bob);
		CUI_EXPECT_TRUE(box.GetGeneratedItem(0) == aliceContainer);
		CUI_EXPECT_TRUE(box.GetGeneratedItem(1) == bobContainer);
		CUI_EXPECT_EQ(1, box.SelectedIndex);

		auto erin = makeRecord(L"Erin", 35, true);
		source->Items.push_back(BindingSourceReference(erin));
		CUI_EXPECT_EQ(3ULL, view->Count());
		CUI_EXPECT_TRUE(view->TryGetItem(1, item));
		CUI_EXPECT_TRUE(item.Shared() == erin);
		CUI_EXPECT_TRUE(box.GetGeneratedItem(0) == aliceContainer);
		CUI_EXPECT_TRUE(box.GetGeneratedItem(2) == bobContainer);
		CUI_EXPECT_EQ(2, box.SelectedIndex);
		CUI_EXPECT_TRUE(std::none_of(changes.begin(), changes.end(),
			[](auto action) { return action == CollectionChangeAction::Reset; }));
	});

	runner.Add("CollectionViewSource refresh guard survives throwing notifications", []
	{
		auto makeRecord = [](const std::wstring& name)
		{
			auto record = std::make_shared<ObservableObject>();
			CUI_EXPECT_TRUE(record->DefineProperty(L"Name", name));
			return BindingSourceReference(record);
		};
		auto source = std::make_shared<ObservableBindingList>(L"Person");
		source->Items.push_back(makeRecord(L"Alpha"));
		source->Items.push_back(makeRecord(L"Beta"));
		source->Items.push_back(makeRecord(L"Gamma"));

		auto view = std::make_shared<CollectionViewSource>();
		bool throwOnce = true;
		auto throwingNotification = view->SubscribeChanged(
			[&](const CollectionChangedEventArgs&)
			{
				if (!throwOnce) return;
				throwOnce = false;
				throw std::runtime_error(
					"intentional projection notification failure");
			});
		bool refreshThrew = false;
		try
		{
			view->SetSource(BindingListReference(source));
		}
		catch (const std::runtime_error&)
		{
			refreshThrew = true;
		}
		CUI_EXPECT_TRUE(refreshThrew);

		// The first pass may have published a prefix, but its re-entrancy guard
		// must be cleared so a second pass can converge the complete projection.
		view->Refresh();
		CUI_EXPECT_EQ(3ULL, view->Count());
		BindingSourceReference item;
		CUI_EXPECT_TRUE(view->TryGetItem(2, item));
		BindingValue name;
		CUI_EXPECT_TRUE(item.Get()->TryGetValue(L"Name", name));
		CUI_EXPECT_EQ(std::wstring(L"Gamma"), name.ToString());

		// Source-driven refresh remains live after the failed user callback too.
		source->Items.push_back(makeRecord(L"Delta"));
		CUI_EXPECT_EQ(4ULL, view->Count());
	});

	runner.Add("Selector synchronizes selection with collection view currency", []
	{
		auto makeRecord = [](const std::wstring& name, int score, bool active)
		{
			auto record = std::make_shared<ObservableObject>();
			CUI_EXPECT_TRUE(record->DefineProperty(L"Name", name));
			CUI_EXPECT_TRUE(record->DefineProperty(L"Score", score));
			CUI_EXPECT_TRUE(record->DefineProperty(L"Active", active));
			return record;
		};

		auto alice = makeRecord(L"Alice", 10, true);
		auto bob = makeRecord(L"Bob", 30, true);
		auto carol = makeRecord(L"Carol", 20, true);
		auto source = std::make_shared<ObservableBindingList>(L"Person");
		for (const auto& record : { alice, bob, carol })
			source->Items.push_back(BindingSourceReference(record));

		auto view = std::make_shared<CollectionViewSource>();
		view->SetFilterDescriptions({ CollectionFilterDescription{
			L"Active", CollectionFilterOperator::Equals,
			BindingValue(true), false } });
		view->SetSortDescriptions({ CollectionSortDescription{
			L"Score", CollectionSortDirection::Descending, false } });
		view->SetSource(BindingListReference(source));
		IBindingListCurrentView* currency = view.get();
		CUI_EXPECT_TRUE(currency != nullptr);
		CUI_EXPECT_EQ(0, currency->CurrentPosition());
		CUI_EXPECT_TRUE(currency->CurrentItem().Shared() == bob);

		ListBox box; ConfigureTestControl(box, 0, 0, 180, 120);
		box.SetDisplayMemberPath(L"Name");
		auto itemTemplate = std::make_shared<TestItemTemplate>(L"Person");
		box.SetItemTemplate(ItemTemplateReference(itemTemplate));
		int selectionChanges = 0;
		box.SelectionChanged += [&selectionChanges](
			Control*, SelectionChangedEventArgs&)
		{
			++selectionChanges;
		};
		int currentChanges = 0;
		auto currentChanged = currency->SubscribeCurrentChanged(
			[&currentChanges] { ++currentChanges; });
		box.SetItemsSource(BindingListReference(view));
		CUI_EXPECT_EQ(-1, box.GetSelectedIndex());
		CUI_EXPECT_FALSE(box.GetIsSynchronizedWithCurrentItem());

		box.SetIsSynchronizedWithCurrentItem(true);
		CUI_EXPECT_TRUE(box.GetIsSynchronizedWithCurrentItem());
		CUI_EXPECT_EQ(DependencyPropertyValueSource::Local,
			box.GetPropertyValueSource(L"IsSynchronizedWithCurrentItem"));
		CUI_EXPECT_EQ(0, box.GetSelectedIndex());
		BindingSourceReference selected;
		CUI_EXPECT_TRUE(box.GetSelectedItem().TryGet(selected));
		CUI_EXPECT_TRUE(selected.Shared() == bob);

		selectionChanges = 0;
		currentChanges = 0;
		CUI_EXPECT_TRUE(currency->MoveCurrentToPosition(1));
		CUI_EXPECT_EQ(1, box.GetSelectedIndex());
		CUI_EXPECT_TRUE(box.GetSelectedItem().TryGet(selected));
		CUI_EXPECT_TRUE(selected.Shared() == carol);
		CUI_EXPECT_EQ(1, currentChanges);
		CUI_EXPECT_EQ(1, selectionChanges);

		selectionChanges = 0;
		currentChanges = 0;
		box.SetSelectedIndex(0);
		CUI_EXPECT_EQ(0, currency->CurrentPosition());
		CUI_EXPECT_TRUE(currency->CurrentItem().Shared() == bob);
		CUI_EXPECT_EQ(1, currentChanges);
		CUI_EXPECT_EQ(1, selectionChanges);

		// A selection handler may make a nested choice while currency is driving
		// the selector. The pending direction must converge both projections
		// after the outer notification unwinds instead of dropping that choice.
		bool redirectNestedSelection = false;
		auto nestedSelection = box.SelectionChanged.Subscribe(
			[&](Control*, SelectionChangedEventArgs&)
			{
				if (!redirectNestedSelection
					|| box.GetSelectedIndex() != 1) return;
				redirectNestedSelection = false;
				box.SetSelectedIndex(2);
			});
		selectionChanges = 0;
		currentChanges = 0;
		redirectNestedSelection = true;
		CUI_EXPECT_TRUE(currency->MoveCurrentToPosition(1));
		CUI_EXPECT_EQ(2, box.GetSelectedIndex());
		CUI_EXPECT_EQ(2, currency->CurrentPosition());
		CUI_EXPECT_TRUE(currency->CurrentItem().Shared() == alice);
		CUI_EXPECT_EQ(2, currentChanges);
		CUI_EXPECT_EQ(2, selectionChanges);

		selectionChanges = 0;
		currentChanges = 0;
		CUI_EXPECT_TRUE(currency->MoveCurrentToPosition(0));
		CUI_EXPECT_EQ(0, box.GetSelectedIndex());
		CUI_EXPECT_EQ(0, currency->CurrentPosition());
		CUI_EXPECT_EQ(1, currentChanges);
		CUI_EXPECT_EQ(1, selectionChanges);

		// A live sort moves the same current record without selector feedback
		// producing extra CurrentChanged notifications.
		currentChanges = 0;
		CUI_EXPECT_TRUE(bob->SetValue(L"Score", 5));
		CUI_EXPECT_EQ(2, currency->CurrentPosition());
		CUI_EXPECT_EQ(2, box.GetSelectedIndex());
		CUI_EXPECT_TRUE(currency->CurrentItem().Shared() == bob);
		CUI_EXPECT_TRUE(box.GetSelectedItem().TryGet(selected));
		CUI_EXPECT_TRUE(selected.Shared() == bob);
		CUI_EXPECT_EQ(1, currentChanges);

		// Filtering out the currency record chooses the view's replacement and
		// drives the selector back to that exact identity.
		currentChanges = 0;
		CUI_EXPECT_TRUE(bob->SetValue(L"Active", false));
		CUI_EXPECT_EQ(1, currency->CurrentPosition());
		CUI_EXPECT_EQ(1, box.GetSelectedIndex());
		CUI_EXPECT_TRUE(currency->CurrentItem().Shared() == alice);
		CUI_EXPECT_TRUE(box.GetSelectedItem().TryGet(selected));
		CUI_EXPECT_TRUE(selected.Shared() == alice);
		CUI_EXPECT_EQ(1, currentChanges);

		auto dora = makeRecord(L"Dora", 50, true);
		auto erin = makeRecord(L"Erin", 40, true);
		auto replacementSource =
			std::make_shared<ObservableBindingList>(L"Person");
		replacementSource->Items.push_back(BindingSourceReference(dora));
		replacementSource->Items.push_back(BindingSourceReference(erin));
		auto replacementView = std::make_shared<CollectionViewSource>();
		replacementView->SetSortDescriptions({ CollectionSortDescription{
			L"Score", CollectionSortDirection::Descending, false } });
		replacementView->SetSource(BindingListReference(replacementSource));
		box.SetItemsSource(BindingListReference(replacementView));
		CUI_EXPECT_EQ(0, box.GetSelectedIndex());
		CUI_EXPECT_TRUE(box.GetSelectedItem().TryGet(selected));
		CUI_EXPECT_TRUE(selected.Shared() == dora);

		// The old current-view subscription is disconnected after a source swap.
		CUI_EXPECT_TRUE(replacementView->MoveCurrentToPosition(1));
		CUI_EXPECT_EQ(1, box.GetSelectedIndex());
		CUI_EXPECT_TRUE(box.GetSelectedItem().TryGet(selected));
		CUI_EXPECT_TRUE(selected.Shared() == erin);
		CUI_EXPECT_TRUE(currency->MoveCurrentToPosition(0));
		CUI_EXPECT_EQ(1, box.GetSelectedIndex());

		box.SetIsSynchronizedWithCurrentItem(false);
		box.SetSelectedIndex(0);
		CUI_EXPECT_EQ(1, replacementView->CurrentPosition());
		CUI_EXPECT_TRUE(replacementView->MoveCurrentToPosition(0));
		CUI_EXPECT_TRUE(replacementView->MoveCurrentToPosition(1));
		CUI_EXPECT_EQ(0, box.GetSelectedIndex());

		box.SetIsSynchronizedWithCurrentItem(true);
		CUI_EXPECT_EQ(1, box.GetSelectedIndex());
		CUI_EXPECT_TRUE(box.GetSelectedItem().TryGet(selected));
		CUI_EXPECT_TRUE(selected.Shared() == erin);

		// A rejected ItemsSource retains both the old source and its currency
		// subscription; the candidate view never becomes observable by Selector.
		auto wrongSource = std::make_shared<ObservableBindingList>(L"Order");
		wrongSource->Items.push_back(BindingSourceReference(
			makeRecord(L"Wrong 1", 2, true)));
		wrongSource->Items.push_back(BindingSourceReference(
			makeRecord(L"Wrong 2", 1, true)));
		auto wrongView = std::make_shared<CollectionViewSource>();
		wrongView->SetSource(BindingListReference(wrongSource));
		box.SetItemsSource(BindingListReference(wrongView));
		CUI_EXPECT_TRUE(box.GetItemsSource().Shared() == replacementView);
		CUI_EXPECT_TRUE(box.LastTemplateError().find(L"DataType")
			!= std::wstring::npos);
		CUI_EXPECT_TRUE(replacementView->MoveCurrentToPosition(0));
		CUI_EXPECT_EQ(0, box.GetSelectedIndex());
		CUI_EXPECT_TRUE(wrongView->MoveCurrentToPosition(1));
		CUI_EXPECT_EQ(0, box.GetSelectedIndex());

		class ThrowOnRecordTemplate final : public IItemTemplate
		{
		public:
			const std::wstring& DataTypeName() const noexcept override
			{
				static const std::wstring typeName = L"Person";
				return typeName;
			}

			std::unique_ptr<Control> Build(
				const BindingSourceReference& item,
				size_t,
				std::wstring* outError) const override
			{
				BindingValue name;
				if (item) (void)item.Get()->TryGetValue(L"Name", name);
				if (name.ToString() == L"Throw")
					throw std::runtime_error("intentional item-template failure");
				if (outError) outError->clear();
				return MakeTestControl<Label>(name.ToString(), 0, 0);
			}
		};

		// Throwing materialization is transactional as well: the old source,
		// visual tree, current-view subscription, and selection all survive.
		auto stableSource = std::make_shared<ObservableBindingList>(L"Person");
		auto stableA = makeRecord(L"Stable A", 1, true);
		auto stableB = makeRecord(L"Stable B", 2, true);
		stableSource->Items.push_back(BindingSourceReference(stableA));
		stableSource->Items.push_back(BindingSourceReference(stableB));
		auto stableView = std::make_shared<CollectionViewSource>();
		stableView->SetSource(BindingListReference(stableSource));

		ListBox throwingBox; ConfigureTestControl(throwingBox, 0, 0, 180, 120);
		throwingBox.SetItemTemplate(ItemTemplateReference(
			std::make_shared<ThrowOnRecordTemplate>()));
		throwingBox.SetItemsSource(BindingListReference(stableView));
		throwingBox.SetIsSynchronizedWithCurrentItem(true);
		auto* stableVisual = throwingBox.GetGeneratedItem(0);
		CUI_EXPECT_TRUE(stableVisual != nullptr);

		auto throwingSource =
			std::make_shared<ObservableBindingList>(L"Person");
		throwingSource->Items.push_back(BindingSourceReference(
			makeRecord(L"Throw", 3, true)));
		throwingSource->Items.push_back(BindingSourceReference(
			makeRecord(L"Candidate B", 4, true)));
		auto throwingView = std::make_shared<CollectionViewSource>();
		throwingView->SetSource(BindingListReference(throwingSource));
		bool templateThrew = false;
		try
		{
			throwingBox.SetItemsSource(BindingListReference(throwingView));
		}
		catch (const std::runtime_error&)
		{
			templateThrew = true;
		}
		CUI_EXPECT_TRUE(templateThrew);
		CUI_EXPECT_TRUE(throwingBox.GetItemsSource().Shared() == stableView);
		CUI_EXPECT_TRUE(throwingBox.GetGeneratedItem(0) == stableVisual);
		CUI_EXPECT_EQ(0, throwingBox.GetSelectedIndex());
		CUI_EXPECT_TRUE(stableView->MoveCurrentToPosition(1));
		CUI_EXPECT_EQ(1, throwingBox.GetSelectedIndex());
		CUI_EXPECT_TRUE(throwingView->MoveCurrentToPosition(1));
		CUI_EXPECT_EQ(1, throwingBox.GetSelectedIndex());
	});

	runner.Add("Selector current-view subscriptions are transactional", []
	{
		class ThrowingSubscriptionView final
			: public IBindingList,
			  public IBindingListCurrentView
		{
		public:
			explicit ThrowingSubscriptionView(
				std::vector<BindingSourceReference> items)
				: _items(std::move(items))
			{
				if (!_items.empty()) _currentPosition = 0;
			}

			size_t Count() const noexcept override { return _items.size(); }
			bool TryGetItem(
				size_t index, BindingSourceReference& out) const override
			{
				if (index >= _items.size() || !_items[index]) return false;
				out = _items[index];
				return true;
			}
			EventConnection SubscribeChanged(ChangedHandler) override
			{
				return {};
			}
			const std::wstring& ItemTypeName() const noexcept override
			{
				static const std::wstring typeName = L"Person";
				return typeName;
			}
			int CurrentPosition() const noexcept override
			{
				return _currentPosition;
			}
			BindingSourceReference CurrentItem() const noexcept override
			{
				return _currentPosition >= 0
					? _items[static_cast<size_t>(_currentPosition)]
					: BindingSourceReference{};
			}
			bool MoveCurrentToPosition(int position) override
			{
				if (position < -1
					|| position >= static_cast<int>(_items.size())) return false;
				if (_currentPosition == position) return true;
				_currentPosition = position;
				cui::framework::EventAccess::Raise(_currentChanged, this);
				return true;
			}
			EventConnection SubscribeCurrentChanged(
				CurrentChangedHandler handler) override
			{
				++SubscribeAttempts;
				if (NotifyDuringSubscribe) handler();
				if (ThrowOnSubscribe)
					throw std::runtime_error(
						"intentional current-view subscription failure");
				return _currentChanged.Subscribe(
					[handler = std::move(handler)](
						ThrowingSubscriptionView*) { handler(); });
			}
			size_t SubscriberCount() const noexcept
			{
				return _currentChanged.Count();
			}

			bool ThrowOnSubscribe = false;
			bool NotifyDuringSubscribe = false;
			int SubscribeAttempts = 0;

		private:
			std::vector<BindingSourceReference> _items;
			int _currentPosition = -1;
			Event<void(ThrowingSubscriptionView*)> _currentChanged;
		};

		auto makeRecord = [](const std::wstring& name)
		{
			auto record = std::make_shared<ObservableObject>();
			CUI_EXPECT_TRUE(record->DefineProperty(L"Name", name));
			return record;
		};
		auto stableA = makeRecord(L"Stable A");
		auto stableB = makeRecord(L"Stable B");
		auto candidateOnly = makeRecord(L"Candidate only");
		auto stable = std::make_shared<ThrowingSubscriptionView>(
			std::vector<BindingSourceReference>{
				BindingSourceReference(stableA),
				BindingSourceReference(stableB) });
		auto candidate = std::make_shared<ThrowingSubscriptionView>(
			std::vector<BindingSourceReference>{
				BindingSourceReference(candidateOnly) });

		ListBox box; ConfigureTestControl(box, 0, 0, 180, 120);
		box.SetDisplayMemberPath(L"Name");
		box.SetItemsSource(BindingListReference(stable));
		box.SetIsSynchronizedWithCurrentItem(true);
		CUI_EXPECT_EQ(1ULL, stable->SubscriberCount());
		CUI_EXPECT_TRUE(stable->MoveCurrentToPosition(1));
		CUI_EXPECT_EQ(1, box.GetSelectedIndex());
		auto* stableVisual = box.GetGeneratedItem(0);
		CUI_EXPECT_TRUE(stableVisual != nullptr);

		candidate->NotifyDuringSubscribe = true;
		candidate->ThrowOnSubscribe = true;
		bool swapThrew = false;
		try
		{
			box.SetItemsSource(BindingListReference(candidate));
		}
		catch (const std::runtime_error&)
		{
			swapThrew = true;
		}
		CUI_EXPECT_TRUE(swapThrew);
		CUI_EXPECT_TRUE(box.GetItemsSource().Shared() == stable);
		CUI_EXPECT_TRUE(box.GetGeneratedItem(0) == stableVisual);
		CUI_EXPECT_EQ(1, box.GetSelectedIndex());
		BindingSourceReference restoredItem;
		CUI_EXPECT_TRUE(box.GetSelectedItem().TryGet(restoredItem));
		CUI_EXPECT_TRUE(restoredItem.Shared() == stableB);
		CUI_EXPECT_EQ(1ULL, stable->SubscriberCount());
		CUI_EXPECT_EQ(0ULL, candidate->SubscriberCount());
		// Every candidate visual and selection observer must be disconnected.
		CUI_EXPECT_EQ(0ULL, candidateOnly->PropertyChanged().Count());
		CUI_EXPECT_TRUE(candidate->MoveCurrentToPosition(-1));
		CUI_EXPECT_TRUE(candidate->MoveCurrentToPosition(0));
		CUI_EXPECT_EQ(1, box.GetSelectedIndex());
		CUI_EXPECT_TRUE(stable->MoveCurrentToPosition(0));
		CUI_EXPECT_EQ(0, box.GetSelectedIndex());

		// A plain old source has no currency subscription for the symmetric
		// OnItemsSourceChanged rollback to resynchronize. This is the case that
		// requires the derived transaction token instead of merely reconnecting.
		auto plainB = makeRecord(L"Plain duplicate");
		auto plain = std::make_shared<ObservableBindingList>(L"Person");
		// Repeated identity verifies that rollback preserves the exact selected
		// occurrence instead of identity-searching back to the first duplicate.
		plain->Items.push_back(BindingSourceReference(plainB));
		plain->Items.push_back(BindingSourceReference(plainB));
		ListBox identityBox; ConfigureTestControl(identityBox, 0, 0, 180, 120);
		identityBox.SetDisplayMemberPath(L"Name");
		identityBox.SetItemsSource(BindingListReference(plain));
		identityBox.SetSelectedIndex(1);
		identityBox.SetIsSynchronizedWithCurrentItem(true);
		auto* plainVisual = identityBox.GetGeneratedItem(0);
		CUI_EXPECT_TRUE(plainVisual != nullptr);
		bool identitySwapThrew = false;
		try
		{
			identityBox.SetItemsSource(BindingListReference(candidate));
		}
		catch (const std::runtime_error&)
		{
			identitySwapThrew = true;
		}
		CUI_EXPECT_TRUE(identitySwapThrew);
		CUI_EXPECT_TRUE(identityBox.GetItemsSource().Shared() == plain);
		CUI_EXPECT_TRUE(identityBox.GetGeneratedItem(0) == plainVisual);
		CUI_EXPECT_EQ(1, identityBox.GetSelectedIndex());
		BindingSourceReference identityRestoredItem;
		CUI_EXPECT_TRUE(
			identityBox.GetSelectedItem().TryGet(identityRestoredItem));
		CUI_EXPECT_TRUE(identityRestoredItem.Shared() == plainB);
		CUI_EXPECT_EQ(0ULL, candidate->SubscriberCount());
		CUI_EXPECT_EQ(0ULL, candidateOnly->PropertyChanged().Count());

		// A source switch raised from a selection callback would otherwise
		// overwrite the outer transaction's stacked host/generator state. Reject
		// it explicitly and let the outer switch restore the committed source.
		auto nested = std::make_shared<ObservableBindingList>(L"Person");
		nested->Items.push_back(BindingSourceReference(
			makeRecord(L"Nested")));
		int reentrantAttempts = 0;
		auto reentrant = identityBox.SelectionChanged.Subscribe(
			[&](Control*, SelectionChangedEventArgs&)
			{
				++reentrantAttempts;
				identityBox.SetItemsSource(BindingListReference(nested));
			});
		bool reentrantSwapThrew = false;
		try
		{
			identityBox.SetItemsSource(BindingListReference(candidate));
		}
		catch (const std::logic_error&)
		{
			reentrantSwapThrew = true;
		}
		reentrant.Disconnect();
		CUI_EXPECT_TRUE(reentrantSwapThrew);
		CUI_EXPECT_TRUE(reentrantAttempts > 0);
		CUI_EXPECT_TRUE(identityBox.GetItemsSource().Shared() == plain);
		CUI_EXPECT_TRUE(identityBox.GetGeneratedItem(0) == plainVisual);
		CUI_EXPECT_EQ(1, identityBox.GetSelectedIndex());
		CUI_EXPECT_TRUE(
			identityBox.GetSelectedItem().TryGet(identityRestoredItem));
		CUI_EXPECT_TRUE(identityRestoredItem.Shared() == plainB);
		const auto restoredIndexSource =
			identityBox.GetPropertyValueSource(L"SelectedIndex");
		BindingValue restoredIndexValue;
		CUI_EXPECT_TRUE(restoredIndexSource
			!= DependencyPropertyValueSource::Default);
		CUI_EXPECT_TRUE(identityBox.TryGetPropertyValue(
			L"SelectedIndex", restoredIndexSource, restoredIndexValue));
		int storedRestoredIndex = -1;
		CUI_EXPECT_TRUE(restoredIndexValue.TryGet(storedRestoredIndex));
		CUI_EXPECT_EQ(1, storedRestoredIndex);
		CUI_EXPECT_EQ(0ULL, candidateOnly->PropertyChanged().Count());

		class ThrowAfterLiveSelectionRebuild final : public Selector
		{
		public:
			using Selector::Selector;
			bool ThrowAfterNextRebuild = false;

		protected:
			void OnGeneratedItemsRebuilt() override
			{
				Selector::OnGeneratedItemsRebuilt();
				if (!ThrowAfterNextRebuild) return;
				ThrowAfterNextRebuild = false;
				throw std::runtime_error(
					"intentional selector rebuild failure");
			}
		};
		auto liveA = makeRecord(L"Live A");
		auto liveB = makeRecord(L"Live B");
		auto live = std::make_shared<ObservableBindingList>(L"Person");
		live->Items.push_back(BindingSourceReference(liveA));
		live->Items.push_back(BindingSourceReference(liveB));
		ThrowAfterLiveSelectionRebuild liveBox;
		ConfigureTestControl(liveBox, 0, 0, 180, 120);
		liveBox.SetDisplayMemberPath(L"Name");
		liveBox.SetItemsSource(BindingListReference(live));
		liveBox.SetSelectedIndex(1);
		liveBox.ThrowAfterNextRebuild = true;
		bool liveChangeThrew = false;
		try
		{
			live->Items.pop_back();
		}
		catch (const std::runtime_error&)
		{
			liveChangeThrew = true;
		}
		CUI_EXPECT_TRUE(liveChangeThrew);
		CUI_EXPECT_TRUE(liveBox.GetItemsSource().Shared() != live);
		CUI_EXPECT_EQ(2ULL, liveBox.ItemCount());
		CUI_EXPECT_EQ(1, liveBox.GetSelectedIndex());
		BindingSourceReference liveRestoredItem;
		CUI_EXPECT_TRUE(liveBox.GetSelectedItem().TryGet(liveRestoredItem));
		CUI_EXPECT_TRUE(liveRestoredItem.Shared() == liveB);

		// Enabling the property itself is transactional as well: a throwing
		// subscription restores both the effective property and backing value.
		ListBox enableBox; ConfigureTestControl(enableBox, 0, 0, 180, 120);
		enableBox.SetDisplayMemberPath(L"Name");
		enableBox.SetItemsSource(BindingListReference(candidate));
		bool enableThrew = false;
		try
		{
			enableBox.SetIsSynchronizedWithCurrentItem(true);
		}
		catch (const std::runtime_error&)
		{
			enableThrew = true;
		}
		CUI_EXPECT_TRUE(enableThrew);
		CUI_EXPECT_FALSE(enableBox.GetIsSynchronizedWithCurrentItem());
		CUI_EXPECT_EQ(-1, enableBox.GetSelectedIndex());
		BindingValue effectiveSynchronization;
		CUI_EXPECT_TRUE(enableBox.TryGetPropertyValue(
			L"IsSynchronizedWithCurrentItem", effectiveSynchronization));
		bool synchronized = true;
		CUI_EXPECT_TRUE(effectiveSynchronization.TryGet(synchronized));
		CUI_EXPECT_FALSE(synchronized);
		CUI_EXPECT_EQ(0ULL, candidate->SubscriberCount());

		candidate->ThrowOnSubscribe = false;
		enableBox.SetIsSynchronizedWithCurrentItem(true);
		CUI_EXPECT_TRUE(enableBox.GetIsSynchronizedWithCurrentItem());
		CUI_EXPECT_EQ(1ULL, candidate->SubscriberCount());
		CUI_EXPECT_EQ(0, enableBox.GetSelectedIndex());
		enableBox.SetIsSynchronizedWithCurrentItem(false);
		CUI_EXPECT_EQ(0ULL, candidate->SubscriberCount());
	});

	runner.Add("Selector current-item convergence is iteration bounded", []
	{
		auto source = std::make_shared<ObservableBindingList>(L"Person");
		for (const auto* name : { L"Alpha", L"Beta" })
		{
			auto record = std::make_shared<ObservableObject>();
			CUI_EXPECT_TRUE(record->DefineProperty(L"Name", std::wstring(name)));
			source->Items.push_back(BindingSourceReference(record));
		}
		auto view = std::make_shared<CollectionViewSource>();
		view->SetSource(BindingListReference(source));
		ListBox box; ConfigureTestControl(box, 0, 0, 180, 120);
		box.SetDisplayMemberPath(L"Name");
		box.SetItemsSource(BindingListReference(view));
		box.SetIsSynchronizedWithCurrentItem(true);

		int adversarialSelectionChanges = 0;
		auto oscillation = box.SelectionChanged.Subscribe(
			[&](Control*, SelectionChangedEventArgs&)
			{
				++adversarialSelectionChanges;
				const int opposite = box.GetSelectedIndex() == 0 ? 1 : 0;
				(void)view->MoveCurrentToPosition(opposite);
			});
		CUI_EXPECT_TRUE(view->MoveCurrentToPosition(1));
		CUI_EXPECT_TRUE(adversarialSelectionChanges > 0);
		CUI_EXPECT_TRUE(adversarialSelectionChanges <= 64);

		// Removing the adversarial handler allows the next independent change
		// to start a fresh pass and converge normally.
		oscillation.Disconnect();
		CUI_EXPECT_TRUE(view->MoveCurrentToPosition(box.GetSelectedIndex()));
		CUI_EXPECT_EQ(view->CurrentPosition(), box.GetSelectedIndex());
		box.SetSelectedIndex(box.GetSelectedIndex() == 0 ? 1 : 0);
		CUI_EXPECT_EQ(view->CurrentPosition(), box.GetSelectedIndex());
	});

	runner.Add("CollectionViewSource builds hierarchical live groups", []
	{
		auto makeRecord = [](const std::wstring& name,
			const std::wstring& department, const std::wstring& team, int score)
		{
			auto record = std::make_shared<ObservableObject>();
			CUI_EXPECT_TRUE(record->DefineProperty(L"Name", name));
			CUI_EXPECT_TRUE(record->DefineProperty(L"Department", department));
			CUI_EXPECT_TRUE(record->DefineProperty(L"Team", team));
			CUI_EXPECT_TRUE(record->DefineProperty(L"Score", score));
			return record;
		};
		auto alice = makeRecord(L"Alice", L"Engineering", L"Core", 20);
		auto bob = makeRecord(L"Bob", L"Sales", L"East", 30);
		auto carol = makeRecord(L"Carol", L"Engineering", L"UI", 40);
		auto dora = makeRecord(L"Dora", L"Engineering", L"Core", 50);
		auto source = std::make_shared<ObservableBindingList>(L"Person");
		for (const auto& item : { alice, bob, carol, dora })
			source->Items.push_back(BindingSourceReference(item));

		auto view = std::make_shared<CollectionViewSource>();
		view->SetGroupDescriptions({
			{ L"Department", CollectionSortDirection::Ascending, true },
			{ L"Team", CollectionSortDirection::Descending, true } });
		view->SetAggregateDescriptions({
			{ L"RecordCount", L"", CollectionAggregateFunction::Count },
			{ L"TotalScore", L"Score", CollectionAggregateFunction::Sum },
			{ L"AverageScore", L"Score", CollectionAggregateFunction::Average },
			{ L"MaxScore", L"Score", CollectionAggregateFunction::Max } });
		view->SetSortDescriptions({
			{ L"Score", CollectionSortDirection::Descending, false } });
		int groupsChanged = 0;
		auto groupConnection = view->SubscribeGroupsChanged(
			[&] { ++groupsChanged; });
		std::vector<CollectionChangeAction> changes;
		auto itemConnection = view->SubscribeChanged(
			[&](const auto& change) { changes.push_back(change.Action); });
		view->SetSource(BindingListReference(source));
		CUI_EXPECT_EQ(4ULL, view->Count());
		CUI_EXPECT_EQ(5ULL, view->Groups().size());
		CUI_EXPECT_EQ(std::wstring(L"Engineering"),
			view->Groups()[0].Key.ToString());
		CUI_EXPECT_EQ(0ULL, view->Groups()[0].Level);
		CUI_EXPECT_EQ(0ULL, view->Groups()[0].StartIndex);
		CUI_EXPECT_EQ(3ULL, view->Groups()[0].ItemCount);
		CUI_EXPECT_EQ(std::wstring(L"3"),
			view->Groups()[0].Aggregates.at(L"RecordCount").ToString());
		double aggregateValue = 0.0;
		CUI_EXPECT_TRUE(view->Groups()[0].Aggregates.at(
			L"TotalScore").TryGetDouble(aggregateValue));
		CUI_EXPECT_EQ(110.0, aggregateValue);
		CUI_EXPECT_TRUE(view->Groups()[0].Aggregates.at(
			L"AverageScore").TryGetDouble(aggregateValue));
		CUI_EXPECT_NEAR(110.0 / 3.0, aggregateValue, 0.0001);
		CUI_EXPECT_EQ(std::wstring(L"50"),
			view->Groups()[0].Aggregates.at(L"MaxScore").ToString());
		CUI_EXPECT_EQ(std::wstring(L"UI"), view->Groups()[1].Key.ToString());
		CUI_EXPECT_EQ(1ULL, view->Groups()[1].Level);
		CUI_EXPECT_EQ(1, groupsChanged);

		BindingSourceReference item;
		CUI_EXPECT_TRUE(view->TryGetItem(0, item));
		CUI_EXPECT_TRUE(item.Shared() == carol);
		CUI_EXPECT_TRUE(view->TryGetItem(1, item));
		CUI_EXPECT_TRUE(item.Shared() == dora);
		CUI_EXPECT_TRUE(view->TryGetItem(2, item));
		CUI_EXPECT_TRUE(item.Shared() == alice);

		CUI_EXPECT_TRUE(bob->SetValue(L"Department", std::wstring(L"Engineering")));
		CUI_EXPECT_TRUE(groupsChanged >= 2);
		CUI_EXPECT_EQ(4ULL, view->Groups().front().ItemCount);
		CUI_EXPECT_TRUE(view->Groups().front().Aggregates.at(
			L"TotalScore").TryGetDouble(aggregateValue));
		CUI_EXPECT_EQ(140.0, aggregateValue);
		const int beforeAggregateChange = groupsChanged;
		CUI_EXPECT_TRUE(alice->SetValue(L"Score", 25));
		CUI_EXPECT_TRUE(groupsChanged > beforeAggregateChange);
		CUI_EXPECT_TRUE(view->Groups().front().Aggregates.at(
			L"TotalScore").TryGetDouble(aggregateValue));
		CUI_EXPECT_EQ(145.0, aggregateValue);
		CUI_EXPECT_TRUE(std::none_of(changes.begin(), changes.end(),
			[](auto action) { return action == CollectionChangeAction::Reset; }));
	});

