	runner.Add("Control property metadata coerces defaults and invalidates layout", []
	{
		using namespace cui::core;

		PropertySystemControl target;
		const auto* metadata = target.FindPropertyMetadata(L"Level");
		CUI_EXPECT_TRUE(metadata != nullptr);
		CUI_EXPECT_TRUE(metadata->HasDefaultValue());
		CUI_EXPECT_TRUE(HasDependencyPropertyFlag(
			metadata->Flags(), DependencyPropertyFlags::AffectsMeasure));
		CUI_EXPECT_TRUE(HasDependencyPropertyFlag(
			metadata->Flags(), DependencyPropertyFlags::AffectsRender));

		BindingValue defaultValue;
		int typedDefault = 0;
		CUI_EXPECT_TRUE(metadata->TryGetDefaultValue(defaultValue));
		CUI_EXPECT_TRUE(defaultValue.TryGet(typedDefault));
		CUI_EXPECT_EQ(4, typedDefault);
		CUI_EXPECT_TRUE(target.IsPropertyValueDefault(L"Level"));

		target.Measure(Constraints{ Size{ 200.0f, 100.0f } });
		target.Arrange(Rect{ 0.0f, 0.0f, 120.0f, 20.0f });
		CUI_EXPECT_FALSE(target.GetComputedLayout().NeedsMeasure());

		int notifications = 0;
		std::wstring changedName;
		int oldLevel = -1;
		int newLevel = -1;
		auto connection = target.OnPropertyValueChanged.Subscribe(
			[&](DependencyObject*, const DependencyPropertyChangedEventArgs& e)
			{
				++notifications;
				changedName = e.PropertyName;
				e.OldValue.TryGet(oldLevel);
				e.NewValue.TryGet(newLevel);
			});

		CUI_EXPECT_TRUE(target.TrySetPropertyValue(L"Level", BindingValue(99)));
		CUI_EXPECT_EQ(10, target.GetLevel());
		CUI_EXPECT_EQ(1, notifications);
		CUI_EXPECT_EQ(std::wstring(L"Level"), changedName);
		CUI_EXPECT_EQ(4, oldLevel);
		CUI_EXPECT_EQ(10, newLevel);
		CUI_EXPECT_EQ(1, target.ChangedCallbackCount);
		CUI_EXPECT_TRUE(target.GetComputedLayout().NeedsMeasure());
		CUI_EXPECT_FALSE(target.IsPropertyValueDefault(L"Level"));

		CUI_EXPECT_TRUE(target.TrySetPropertyValue(L"Level", BindingValue(12)));
		CUI_EXPECT_EQ(10, target.GetLevel());
		CUI_EXPECT_EQ(1, notifications);
		CUI_EXPECT_EQ(1, target.ChangedCallbackCount);

		CUI_EXPECT_TRUE(target.ResetPropertyValue(L"Level"));
		CUI_EXPECT_EQ(4, target.GetLevel());
		CUI_EXPECT_EQ(2, notifications);
		CUI_EXPECT_TRUE(target.IsPropertyValueDefault(L"Level"));
		target.SetLevel(-3);
		CUI_EXPECT_EQ(0, target.GetLevel());
		CUI_EXPECT_EQ(3, notifications);
		CUI_EXPECT_EQ(DependencyPropertyValueSource::Local,
			target.GetPropertyValueSource(L"Level"));

		BindingValue current;
		int typedCurrent = -1;
		CUI_EXPECT_TRUE(target.TryGetPropertyValue(L"Level", current));
		CUI_EXPECT_TRUE(current.TryGet(typedCurrent));
		CUI_EXPECT_EQ(0, typedCurrent);
		CUI_EXPECT_FALSE(target.TrySetPropertyValue(
			L"Level", BindingValue(BindingPayload{ 1, L"wrong type" })));
		CUI_EXPECT_FALSE(target.TrySetPropertyValue(L"Missing", BindingValue(1)));
		CUI_EXPECT_FALSE(target.ResetPropertyValue(L"Missing"));

		ObservableObject source;
		source.SetValue(L"Level", 50);
		CUI_EXPECT_TRUE(target.DataBindings.Add(
			L"Level", source, L"Level", BindingMode::TwoWay) != nullptr);
		CUI_EXPECT_EQ(10, target.GetLevel());
		target.SetCurrentLevel(7);
		CUI_EXPECT_EQ(7, source.GetValue<int>(L"Level"));
		source.SetValue(L"Level", 8);
		CUI_EXPECT_EQ(8, target.GetLevel());
	});

	runner.Add("Declarative properties share control metadata and value precedence", []
	{
		Control target;
		DeclarativePropertyDefinition definition;
		definition.Name = L"Severity";
		definition.ValueKind = BindingValueKind::Int;
		definition.DefaultValue = BindingValue(2);
		definition.Flags = DependencyPropertyFlags::AffectsRender;
		definition.Design.DisplayName = L"Severity";
		definition.Design.Category = L"Component";
		definition.Design.Editor = DependencyPropertyEditorKind::Number;
		std::wstring error;
		auto descriptor = CreateDeclarativeTestSchema(
			{ definition }, &error, L"SeverityComponent");
		CUI_EXPECT_TRUE(descriptor != nullptr);
		CUI_EXPECT_TRUE(cui::framework::XamlAccess::SetTypeDescriptor(
			target, descriptor, &error));
		CUI_EXPECT_TRUE(error.empty());
		Control peer;
		CUI_EXPECT_TRUE(cui::framework::XamlAccess::SetTypeDescriptor(
			peer, descriptor, &error));
		CUI_EXPECT_TRUE(
			target.GetDeclarativeTypeDescriptor()
				== peer.GetDeclarativeTypeDescriptor());
		CUI_EXPECT_TRUE(target.FindPropertyMetadata(L"Severity")
			== peer.FindPropertyMetadata(L"Severity"));

		CUI_EXPECT_TRUE(target.FindPropertyMetadata(L"severity") == nullptr);
		const auto* metadata = target.FindPropertyMetadata(L"Severity");
		CUI_EXPECT_TRUE(metadata != nullptr);
		CUI_EXPECT_EQ(BindingValueKind::Int, metadata->ValueKind());
		CUI_EXPECT_TRUE(metadata->CanRead());
		CUI_EXPECT_TRUE(metadata->CanWrite());
		CUI_EXPECT_TRUE(metadata->CanObserve());
		CUI_EXPECT_EQ(DependencyPropertyPersistence::Metadata,
			metadata->Design().Persistence);

		BindingValue value;
		int severity = 0;
		CUI_EXPECT_TRUE(target.TryGetPropertyValue(L"Severity", value));
		CUI_EXPECT_TRUE(value.TryGet(severity));
		CUI_EXPECT_EQ(2, severity);

		int notifications = 0;
		auto connection = target.OnPropertyValueChanged.Subscribe(
			[&](DependencyObject*, const DependencyPropertyChangedEventArgs& args)
			{
				if (args.PropertyName == L"Severity") ++notifications;
			});
		CUI_EXPECT_TRUE(cui::framework::DependencyPropertyAccess::SetValue(
			target, L"Severity", BindingValue(4),
			DependencyPropertyValueSource::Style));
		CUI_EXPECT_TRUE(target.TrySetPropertyValue(L"Severity", BindingValue(7)));
		CUI_EXPECT_EQ(DependencyPropertyValueSource::Local,
			target.GetPropertyValueSource(L"Severity"));
		CUI_EXPECT_TRUE(target.TryGetPropertyValue(L"Severity", value));
		CUI_EXPECT_TRUE(value.TryGet(severity));
		CUI_EXPECT_EQ(7, severity);
		CUI_EXPECT_EQ(2, notifications);
		CUI_EXPECT_TRUE(target.ClearPropertyValue(L"Severity"));
		CUI_EXPECT_TRUE(target.TryGetPropertyValue(L"Severity", value));
		CUI_EXPECT_TRUE(value.TryGet(severity));
		CUI_EXPECT_EQ(4, severity);
		CUI_EXPECT_TRUE(cui::framework::DependencyPropertyAccess::ClearValue(
			target, L"Severity", DependencyPropertyValueSource::Style));
		CUI_EXPECT_TRUE(target.TryGetPropertyValue(L"Severity", value));
		CUI_EXPECT_TRUE(value.TryGet(severity));
		CUI_EXPECT_EQ(2, severity);

		const auto properties = DependencyPropertyRegistry::GetProperties(target);
		CUI_EXPECT_TRUE(std::any_of(properties.begin(), properties.end(),
			[](const DependencyPropertyMetadata* property)
			{
				return property && property->Name() == L"Severity";
			}));
		auto replacement = CreateDeclarativeTestSchema(
			{ definition }, &error, L"SeverityComponent");
		CUI_EXPECT_TRUE(replacement != nullptr);
		XamlSchemaContext schemaContext;
		CUI_EXPECT_TRUE(schemaContext.GetOrAdd(descriptor, &error) == descriptor);
		CUI_EXPECT_TRUE(schemaContext.GetOrAdd(replacement, &error) == descriptor);
		auto divergentDefinition = definition;
		divergentDefinition.DefaultValue = BindingValue(3);
		auto divergent = CreateDeclarativeTestSchema(
			{ divergentDefinition }, &error, L"SeverityComponent");
		CUI_EXPECT_TRUE(divergent != nullptr);
		CUI_EXPECT_TRUE(!schemaContext.GetOrAdd(divergent, &error));
		CUI_EXPECT_TRUE(error.find(L"RuntimeTypeId") != std::wstring::npos);
		CUI_EXPECT_FALSE(cui::framework::XamlAccess::SetTypeDescriptor(
			target, replacement, &error));
		Control nativeCollision;
		definition.Name = L"IsEnabled";
		auto collisionSchema = CreateDeclarativeTestSchema(
			{ definition }, &error, L"NativeCollisionComponent");
		CUI_EXPECT_TRUE(collisionSchema != nullptr);
		CUI_EXPECT_FALSE(cui::framework::XamlAccess::SetTypeDescriptor(
			nativeCollision, collisionSchema, &error));
		definition.Name = L"Bad.Name";
		CUI_EXPECT_TRUE(!CreateDeclarativeTestSchema(
			{ definition }, &error, L"BadNameComponent"));
		definition.Name = L"BadUpdateMode";
		definition.DefaultUpdateMode = DataSourceUpdateMode::Default;
		CUI_EXPECT_TRUE(!CreateDeclarativeTestSchema(
			{ definition }, &error, L"BadUpdateComponent"));
	});

