		CUI_EXPECT_TRUE(fontSize->Step.has_value());
		CUI_EXPECT_EQ(0.5, *fontSize->Step);
		CUI_EXPECT_EQ(DependencyPropertyPersistence::Metadata, fontSize->Persistence);
