		const auto indexOf = [&](const wchar_t* name)
		{
			for (size_t index = 0; index < browsable.size(); ++index)
				if (browsable[index].Name == name)
					return static_cast<int>(index);
			return -1;
		};
		const int widthIndex = indexOf(L"Width");
