		CUI_EXPECT_TRUE(DesignerPropertyCatalog::Find(plain, L"Checked") == nullptr);
		CUI_EXPECT_TRUE(DesignerPropertyCatalog::Find(plain, L"IsChecked") == nullptr);
		CheckBox checkBox;
