		auto* content = static_cast<Panel*>(
			host.SetVisualContent(std::move(contentOwner)));
		auto* combo = AddTestVisual<ComboBox>(
			*content, L"", 12, 12, 160, 28);
		SetTestComboBoxItems(*combo, { L"One", L"Two" });
		host.UpdateLayout();
		combo->SetIsDropDownOpen(true);
