			DesignerPropertyCatalog::Find(properties, L"TabStripPlacement");
		CUI_EXPECT_TRUE(selectedIndex != nullptr);
		CUI_EXPECT_TRUE(placement != nullptr);
		CUI_EXPECT_EQ(DependencyPropertyEditorKind::Choice, placement->Editor);
		CUI_EXPECT_EQ(4ULL, placement->Choices.size());
		CUI_EXPECT_EQ(DependencyPropertyPersistence::Metadata,
			selectedIndex->Persistence);
		for (const wchar_t* removed : {
			L"AnimationMode", L"AnimationDurationMs", L"TitlePosition",
			L"TitleHeight", L"TitleWidth", L"TitleScrollOffset",
			L"EnableTitleScroll", L"AccentColor" })
		{
			CUI_EXPECT_TRUE(DesignerPropertyCatalog::Find(
				properties, removed) == nullptr);
			CUI_EXPECT_TRUE(tabs.FindPropertyMetadata(removed) == nullptr);
		}
		CUI_EXPECT_TRUE(tabs.TrySetPropertyValue(
			L"TabStripPlacement", BindingValue(Dock::Left)));
		CUI_EXPECT_EQ(Dock::Left, tabs.TabStripPlacement);
		CUI_EXPECT_FALSE(tabs.TrySetPropertyValue(
			L"TabStripPlacement", BindingValue(static_cast<Dock>(99))));
		CUI_EXPECT_EQ(Dock::Left, tabs.TabStripPlacement);

