		{
			const auto found = std::find_if(
				document.Nodes.begin(), document.Nodes.end(),
				[&](const auto& node) { return node.Name == name; });
			return found == document.Nodes.end() ? nullptr : &*found;
		};
		const auto* pastedButton = find(merged, L"button2");
