		DesignerModel::DesignDocument upgradedVersion23;
		CUI_EXPECT_FALSE(DesignerModel::DesignDocumentSerializer::FromXml(
			version23, upgradedVersion23, &error));

		DesignerModel::DesignDocument fragment;
