		CUI_EXPECT_TRUE(cui::framework::PresentationAccess::AdvanceVisualStateAnimations(*card, recoveryTick + 150));
		CUI_EXPECT_FALSE(card->HasActiveVisualStateAnimations());
		CUI_EXPECT_NEAR(8.0f, Canvas::GetLeft(*chrome), 0.0001f);

		auto resourceReload = document;
