		CUI_EXPECT_TRUE(transitions != std::string::npos);
		if (transitions != std::string::npos)
			duplicateSelector.insert(transitions
				+ std::string("<VisualStateGroup.Transitions>").size(),
				"<VisualTransition GeneratedDuration=\"0:0:0.050\" />");
		unchanged = document;
