		CUI_EXPECT_TRUE(cui::framework::PresentationAccess::AdvanceVisualStateAnimations(*card, tick + 100));
		expectSize(readExtent(), { 17.8125f, 30.4375f }, 0.45f);
		CUI_EXPECT_TRUE(cui::framework::PresentationAccess::AdvanceVisualStateAnimations(*card, tick + 200));
		expectSize(readExtent(), { 40.5f, 60.25f });

		(void)go(L"Idle");
		tick = go(L"KeyFrames");
		CUI_EXPECT_TRUE(cui::framework::PresentationAccess::AdvanceVisualStateAnimations(*card, tick + 50));
		expectSize(readExtent(), { 12.75f, 23.0f }, 0.35f);
		CUI_EXPECT_TRUE(cui::framework::PresentationAccess::AdvanceVisualStateAnimations(*card, tick + 150));
		expectSize(readExtent(), { 20.25f, 30.5f }, 0.05f);
		CUI_EXPECT_TRUE(cui::framework::PresentationAccess::AdvanceVisualStateAnimations(*card, tick + 200));
		expectSize(readExtent(), { 32.25f, 42.5f }, 0.05f);
		CUI_EXPECT_TRUE(cui::framework::PresentationAccess::AdvanceVisualStateAnimations(*card, tick + 250));
		expectSize(readExtent(), { 36.375f, 49.125f }, 0.35f);
		CUI_EXPECT_TRUE(cui::framework::PresentationAccess::AdvanceVisualStateAnimations(*card, tick + 350));
		expectSize(readExtent(), { 45.5f, 63.25f }, 0.35f);

		(void)go(L"Idle");
		tick = go(L"By");
		CUI_EXPECT_TRUE(cui::framework::PresentationAccess::AdvanceVisualStateAnimations(*card, tick + 100));
		expectSize(readExtent(), { 12.75f, 24.25f });

		(void)go(L"Idle");
		tick = go(L"Additive");
		CUI_EXPECT_TRUE(cui::framework::PresentationAccess::AdvanceVisualStateAnimations(*card, tick + 150));
		expectSize(readExtent(), { 14.75f, 26.0f }, 0.35f);

