		CUI_EXPECT_NEAR(2.0f, rectangle().Rect.left, 0.08f);
		CUI_EXPECT_NEAR(30.0f, rectangle().Rect.right - rectangle().Rect.left, 0.08f);
		CUI_EXPECT_NEAR(5.0f, rectangle().RadiusX, 0.08f);
