		CUI_EXPECT_NEAR(8.0f, rectangle().RadiusX, 0.001f);
		CUI_EXPECT_NEAR(50.0f, ellipse().Center.x, 0.001f);
		CUI_EXPECT_NEAR(12.0f, ellipse().RadiusY, 0.001f);
