	runner.Add("Application resource sources are configurable and extensible", []
	{
		struct ResolverRestore final
		{
			std::shared_ptr<const ResourceResolver> Previous =
				Application::GetResourceResolver();
			~ResolverRestore() { Application::SetResourceResolver(Previous); }
		} restore;

		class MemoryResourceSource final : public IResourceSource
		{
		public:
			ResourceResolveStatus Resolve(
				const ResourceRequest& request,
				ResolvedResource& output,
				std::wstring*) const override
			{
				if (request.Uri != L"memory://theme")
					return ResourceResolveStatus::NotHandled;
				const std::string content =
					R"(<ResourceDictionary xmlns="urn:cui" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"><Color x:Key="Accent">#FF123456</Color></ResourceDictionary>)";
				output = {};
				output.RequestedUri = request.Uri;
				output.Identity = L"memory://theme";
				output.BaseUri = L"memory://";
				output.Bytes.assign(content.begin(), content.end());
				output.Dependency.Identity = output.Identity;
				return ResourceResolveStatus::Resolved;
			}
		};

		auto resolver = std::make_shared<ResourceResolver>();
		resolver->AddSource(std::make_shared<MemoryResourceSource>());
		Application::SetResourceResolver(resolver);
		DesignerModel::DesignDocument memoryDocument;
		std::wstring error;
		CUI_EXPECT_TRUE(DesignerModel::XamlDocumentParser::FromXaml(
			R"(<Window xmlns="urn:cui"><Window.Resources><ResourceDictionary><ResourceDictionary.MergedDictionaries><ResourceDictionary Source="memory://theme"/></ResourceDictionary.MergedDictionaries></ResourceDictionary></Window.Resources></Window>)",
			memoryDocument, &error));
		CUI_EXPECT_EQ(1ULL, memoryDocument.StyleSheet.Resources.size());
		CUI_EXPECT_EQ(std::wstring(L"Accent"),
			memoryDocument.StyleSheet.Resources.front().Key);
		const auto memoryDependencies = memoryDocument.ResourceDependencies();
		CUI_EXPECT_EQ(1ULL, memoryDependencies.size());
		CUI_EXPECT_TRUE(memoryDependencies.front().WatchPath.empty());

		namespace fs = std::filesystem;
		const auto root = fs::temp_directory_path()
			/ ("cui-resource-roots-" + std::to_string(
				std::chrono::steady_clock::now().time_since_epoch().count()));
		fs::create_directories(root);
		const auto documentPath = root / "Configured.cui.xaml";
		{
			std::ofstream stream(documentPath, std::ios::binary);
			stream << R"(<Window xmlns="urn:cui" x:Name="ConfiguredWindow" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"><TextBlock Text="Configured"/></Window>)";
		}
		Application::ConfigureResourceDirectories({ root.wstring() });
		{
			std::ofstream stream(root / "configured.svg", std::ios::binary);
			stream << R"(<svg xmlns="http://www.w3.org/2000/svg" width="2" height="2"><rect width="2" height="2" fill="#123456"/></svg>)";
		}
		CUI_EXPECT_TRUE(cui::resources::LoadBitmapResource(
			L"configured.svg") != nullptr);
		DesignerModel::DesignDocument fileDocument;
		CUI_EXPECT_TRUE(DesignerModel::XamlDocumentParser::LoadFromFile(
			L"Configured.cui.xaml", fileDocument, &error));
		CUI_EXPECT_EQ(std::wstring(L"ConfiguredWindow"), fileDocument.Window.Name);
		CUI_EXPECT_EQ(root.lexically_normal().wstring(),
			fileDocument.ResourceBasePath);
		CUI_EXPECT_EQ(1ULL, fileDocument.ResourceDependencies().size());
		fs::remove_all(root);
	});

	runner.Add("XAML preserves Hidden and rejects writes to effective IsVisible", []
	{
		const std::string xaml = R"XAML(<Window xmlns="urn:cui"
  xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" x:Name="VisibilityWindow">
  <StackPanel x:Name="hiddenHost" Visibility="Hidden">
    <Button x:Name="visibleChild" Content="Child" />
  </StackPanel>
</Window>)XAML";
		DesignerModel::DesignDocument document;
		std::wstring error;
		CUI_EXPECT_TRUE(DesignerModel::XamlDocumentParser::FromXaml(
			xaml, document, &error));
		CUI_EXPECT_EQ(std::wstring(L"Hidden"),
			DesignNodePropertyText(document.Nodes.front(), L"Visibility"));
		const auto canonical =
			DesignerModel::XamlDocumentSerializer::ToXaml(document);
		CUI_EXPECT_TRUE(canonical.find("Visibility=\"Hidden\"")
			!= std::string::npos);
		CUI_EXPECT_TRUE(canonical.find("Visibility=\"false\"")
			== std::string::npos);

		DesignerModel::RuntimeDocument runtime;
		CUI_EXPECT_TRUE(DesignerModel::RuntimeDocumentLoader::Load(
			document, runtime, {}, &error));
		auto* host = runtime.FindControlByName(L"hiddenHost");
		auto* child = runtime.FindControlByName(L"visibleChild");
		CUI_EXPECT_TRUE(host != nullptr && child != nullptr);
		if (host && child)
		{
			CUI_EXPECT_TRUE(host->Visibility == Visibility::Hidden);
			CUI_EXPECT_FALSE(host->IsVisible);
			CUI_EXPECT_TRUE(child->Visibility == Visibility::Visible);
			CUI_EXPECT_FALSE(child->IsVisible);
		}

		DesignerModel::DesignDocument rejected;
		CUI_EXPECT_FALSE(DesignerModel::XamlDocumentParser::FromXaml(
			R"(<Window xmlns="urn:cui"><Button IsVisible="false"/></Window>)",
			rejected, &error));
		CUI_EXPECT_TRUE(error.find(L"IsVisible") != std::wstring::npos);
	});

	runner.Add("XAML syntax diagnostics expose Unicode editor coordinates transactionally", []
	{
		std::string malformed =
			"<Window xmlns=\"urn:cui\">\n  <Button Content=\"";
		malformed += "\xE4\xB8\xAD\xE6\x96\x87";
		malformed += "\" Broken=>\n</Window>";
		const std::wstring utf16Source =
			L"<Window xmlns=\"urn:cui\">\n  <Button Content=\""
			L"\x4E2D\x6587" L"\" Broken=>\n</Window>";
		const auto expectedOffset = utf16Source.find(L"=>") + 1;
		const auto secondLine = utf16Source.find(L'\n') + 1;

		DesignerModel::DesignDocument document;
		document.Window.Name = L"PreserveMe";
		const auto baseline = document;
		std::wstring error;
		DesignerModel::XamlDocumentDiagnostic diagnostic;
		CUI_EXPECT_FALSE(DesignerModel::XamlDocumentParser::FromXaml(
			malformed, document, &error, &diagnostic));
		CUI_EXPECT_EQ(baseline, document);
		CUI_EXPECT_FALSE(error.empty());
		CUI_EXPECT_EQ(error, diagnostic.Message);
		CUI_EXPECT_TRUE(diagnostic.HasLocation());
		CUI_EXPECT_TRUE(diagnostic.HasSourceOffset());
		CUI_EXPECT_EQ(2ULL, static_cast<unsigned long long>(diagnostic.Line));
		CUI_EXPECT_EQ(
			static_cast<unsigned long long>(expectedOffset - secondLine + 1),
			static_cast<unsigned long long>(diagnostic.Column));
		CUI_EXPECT_EQ(
			static_cast<unsigned long long>(expectedOffset),
			static_cast<unsigned long long>(diagnostic.Utf16Offset));
	});

	runner.Add("XAML semantic diagnostics locate failing attributes and elements", []
	{
		std::string invalidProperty =
			"<Window xmlns=\"urn:cui\">\r\n  <Button Content=\"";
		invalidProperty += "\xE4\xB8\xAD\xE6\x96\x87";
		invalidProperty += "\" Visibility=\"Vanished\"/>\r\n</Window>";
		const std::wstring propertySource =
			L"<Window xmlns=\"urn:cui\">\r\n  <Button Content=\""
			L"\x4E2D\x6587" L"\" Visibility=\"Vanished\"/>\r\n</Window>";
		const auto propertyOffset = propertySource.find(L"Visibility");
		const auto propertyPosition = CuiTextEdit::GetTextPosition(
			propertySource, propertyOffset);

		DesignerModel::DesignDocument document;
		document.Window.Name = L"PreserveSemanticBaseline";
		const auto baseline = document;
		std::wstring error;
		DesignerModel::XamlDocumentDiagnostic diagnostic;
		CUI_EXPECT_FALSE(DesignerModel::XamlDocumentParser::FromXaml(
			invalidProperty, document, &error, &diagnostic));
		CUI_EXPECT_EQ(baseline, document);
		CUI_EXPECT_EQ(error, diagnostic.Message);
		CUI_EXPECT_TRUE(diagnostic.HasLocation());
		CUI_EXPECT_TRUE(diagnostic.HasSourceOffset());
		CUI_EXPECT_EQ(
			static_cast<unsigned long long>(propertyOffset),
			static_cast<unsigned long long>(diagnostic.Utf16Offset));
		CUI_EXPECT_EQ(
			static_cast<unsigned long long>(propertyPosition.line),
			static_cast<unsigned long long>(diagnostic.Line));
		CUI_EXPECT_EQ(
			static_cast<unsigned long long>(propertyPosition.column),
			static_cast<unsigned long long>(diagnostic.Column));

		const std::string invalidElement =
			"<Window xmlns=\"urn:cui\">\n  <UnknownWidget/>\n</Window>";
		const std::wstring elementSource =
			L"<Window xmlns=\"urn:cui\">\n  <UnknownWidget/>\n</Window>";
		const auto elementOffset = elementSource.find(L"UnknownWidget");
		diagnostic = {};
		CUI_EXPECT_FALSE(DesignerModel::XamlDocumentParser::FromXaml(
			invalidElement, document, &error, &diagnostic));
		CUI_EXPECT_EQ(baseline, document);
		CUI_EXPECT_EQ(
			static_cast<unsigned long long>(elementOffset),
			static_cast<unsigned long long>(diagnostic.Utf16Offset));
	});

	runner.Add("Normalized XAML spans survive into materialization runtime and codegen diagnostics", []
	{
		const std::string xaml = R"XAML(<Window xmlns="urn:cui"
  xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
  <Button x:Name="sourceButton" DesignId="1" Content="Source"
          FontFamily="Consolas" FontSize="18"/>
</Window>)XAML";
		const std::wstring source = Convert::Utf8ToUnicode(xaml);
		const auto elementOffset = source.find(L"Button");
		const auto memberOffset = source.find(L"FontSize");

		DesignerModel::DesignDocument document;
		std::wstring error;
		DesignerModel::XamlDocumentDiagnostic diagnostic;
		CUI_EXPECT_TRUE(DesignerModel::XamlDocumentParser::FromXaml(
			xaml, document, &error, &diagnostic));
		CUI_EXPECT_EQ(1ULL, document.Nodes.size());
		const auto& node = document.Nodes.front();
		CUI_EXPECT_TRUE(node.Source.Element.Valid());
		CUI_EXPECT_EQ(static_cast<unsigned long long>(elementOffset),
			static_cast<unsigned long long>(node.Source.Element.Utf16Offset));
		const auto* fontSpan = node.Source.FindMember(L"FontSize");
		CUI_EXPECT_TRUE(fontSpan != nullptr && fontSpan->Valid());
		if (fontSpan)
		{
			CUI_EXPECT_EQ(static_cast<unsigned long long>(memberOffset),
				static_cast<unsigned long long>(fontSpan->Utf16Offset));
			CUI_EXPECT_TRUE(fontSpan->Utf16Length
				>= std::wstring(L"FontSize=\"18\"").size());
			CUI_EXPECT_TRUE(fontSpan->EndColumn > fontSpan->Column);
		}

		auto* assignment = document.Nodes.front().Properties.Find(L"FontSize");
		CUI_EXPECT_TRUE(assignment != nullptr);
		if (assignment) assignment->Value.Text = L"999";
		CuiRuntime::XamlObjectTree tree;
		diagnostic = {};
		CUI_EXPECT_FALSE(CuiRuntime::XamlObjectMaterializer::Materialize(
			document, tree, &error, &diagnostic));
		CUI_EXPECT_EQ(DesignerModel::XamlDiagnosticStage::Materialize,
			diagnostic.Stage);
		CUI_EXPECT_EQ(std::wstring(L"Button"), diagnostic.QName);
		CUI_EXPECT_EQ(std::wstring(L"FontSize"), diagnostic.Member);
		CUI_EXPECT_EQ(static_cast<unsigned long long>(memberOffset),
			static_cast<unsigned long long>(diagnostic.Utf16Offset));
		CUI_EXPECT_TRUE(diagnostic.Utf16Length > 0);

		DesignerModel::RuntimeDocument runtime;
		diagnostic = {};
		CUI_EXPECT_FALSE(DesignerModel::RuntimeDocumentLoader::Load(
			document, runtime, {}, &error, &diagnostic));
		CUI_EXPECT_EQ(DesignerModel::XamlDiagnosticStage::Materialize,
			diagnostic.Stage);
		CUI_EXPECT_EQ(static_cast<unsigned long long>(memberOffset),
			static_cast<unsigned long long>(diagnostic.Utf16Offset));

		diagnostic = {};
		CUI_EXPECT_FALSE(CodeGenerator::ValidateDocument(
			document, &error, &diagnostic));
		CUI_EXPECT_EQ(DesignerModel::XamlDiagnosticStage::CodeGeneration,
			diagnostic.Stage);
		CUI_EXPECT_EQ(static_cast<unsigned long long>(memberOffset),
			static_cast<unsigned long long>(diagnostic.Utf16Offset));
	});

	runner.Add("Text search replace and caret coordinates stay editor consistent", []
	{
		const std::wstring text = L"Alpha alpha ALPHA";
		CuiTextEdit::FindOptions insensitive;
		CUI_EXPECT_EQ(0, CuiTextEdit::FindText(text, L"alpha", 0, false, insensitive));
		CUI_EXPECT_EQ(6, CuiTextEdit::FindText(text, L"alpha", 1, false, insensitive));
		CUI_EXPECT_EQ(12, CuiTextEdit::FindText(text, L"alpha", -1, true, insensitive));

		CuiTextEdit::FindOptions exact;
		exact.matchCase = true;
		exact.wrap = false;
		CUI_EXPECT_EQ(6, CuiTextEdit::FindText(text, L"alpha", 0, false, exact));
		CUI_EXPECT_EQ(-1, CuiTextEdit::FindText(text, L"alpha", 7, false, exact));
		CUI_EXPECT_FALSE(CuiTextEdit::MatchesAt(text, L"alpha", 0, true));
		CUI_EXPECT_TRUE(CuiTextEdit::MatchesAt(text, L"alpha", 0, false));

		const auto replaced = CuiTextEdit::ReplaceAllText(
			text, L"alpha", L"item", false);
		CUI_EXPECT_EQ(3ULL,
			static_cast<unsigned long long>(replaced.replacements));
		CUI_EXPECT_EQ(std::wstring(L"item item item"), replaced.text);
		const auto nonOverlapping = CuiTextEdit::ReplaceAllText(
			L"aaaa", L"aa", L"b", true);
		CUI_EXPECT_EQ(2ULL,
			static_cast<unsigned long long>(nonOverlapping.replacements));
		CUI_EXPECT_EQ(std::wstring(L"bb"), nonOverlapping.text);
		const auto unchanged = CuiTextEdit::ReplaceAllText(
			text, L"", L"ignored", false);
		CUI_EXPECT_EQ(0ULL,
			static_cast<unsigned long long>(unchanged.replacements));
		CUI_EXPECT_EQ(text, unchanged.text);

		const std::wstring positions = L"A\r\n\xD83D\xDE00" L"B\nZ";
		const auto firstLine = CuiTextEdit::GetTextPosition(positions, 1);
		CUI_EXPECT_EQ(1ULL, static_cast<unsigned long long>(firstLine.line));
		CUI_EXPECT_EQ(2ULL, static_cast<unsigned long long>(firstLine.column));
		const auto secondLine = CuiTextEdit::GetTextPosition(positions, 3);
		CUI_EXPECT_EQ(2ULL, static_cast<unsigned long long>(secondLine.line));
		CUI_EXPECT_EQ(1ULL, static_cast<unsigned long long>(secondLine.column));
		const auto afterEmoji = CuiTextEdit::GetTextPosition(positions, 5);
		CUI_EXPECT_EQ(2ULL, static_cast<unsigned long long>(afterEmoji.line));
		CUI_EXPECT_EQ(2ULL, static_cast<unsigned long long>(afterEmoji.column));
		const auto thirdLine = CuiTextEdit::GetTextPosition(positions, 7);
		CUI_EXPECT_EQ(3ULL, static_cast<unsigned long long>(thirdLine.line));
		CUI_EXPECT_EQ(1ULL, static_cast<unsigned long long>(thirdLine.column));

		RichTextBox editor; ConfigureTestControl(editor, L"alpha beta", 0, 0, 240, 100);
		int selectionChanges = 0;
		editor.SelectionChanged +=
			[&selectionChanges](Control*, SelectionChangedEventArgs&)
			{ selectionChanges++; };
		editor.Select(0, 5);
		CUI_EXPECT_EQ(1, selectionChanges);
		editor.Select(0, 5);
		CUI_EXPECT_EQ(1, selectionChanges);
		editor.InsertText(L"");
		CUI_EXPECT_EQ(std::wstring(L" beta"), editor.Text);
		CUI_EXPECT_EQ(2, selectionChanges);
		editor.Undo();
		CUI_EXPECT_EQ(std::wstring(L"alpha beta"), editor.Text);
		CUI_EXPECT_EQ(3, selectionChanges);
		CUI_EXPECT_EQ(5, editor.GetSelectionLength());
	});

