		{
			CUI_EXPECT_TRUE(text.HandlesNavigationKey(key));
			CUI_EXPECT_TRUE(rich.HandlesNavigationKey(key));
			CUI_EXPECT_TRUE(password.HandlesNavigationKey(key));
			CUI_EXPECT_TRUE(numeric.HandlesNavigationKey(key));
		}

		CUI_EXPECT_FALSE(cui::framework::InputAccess::DispatchInput(
			text, KeyInput(InputReportKind::KeyDown, Key::Space)));
