		CUI_EXPECT_FALSE(fs::exists(outputDir / L"Invalid.cpp.g.h"));

		if (GetEnvironmentVariableW(
			L"CUI_KEEP_CODEGEN_TEST_OUTPUT", nullptr, 0) == 0)
			fs::remove_all(outputDir);
