    runner.Add("Explicit dimensions take precedence over Stretch during arrange", []
    {
        using namespace cui::core;
        using cui::layout::Length;

        const auto configureFixedChild = [](Control& child)
        {
            child.Width = Length::Fixed(40.0f);
            child.Height = Length::Fixed(10.0f);
            CUI_EXPECT_EQ(HorizontalAlignment::Stretch,
                child.HorizontalAlignment);
            CUI_EXPECT_EQ(VerticalAlignment::Stretch,
                child.VerticalAlignment);
        };

        {
            Control container;
            auto* child = container.AdoptVisualChild(
                new FractionalMeasureControl(Size{ 12.0f, 8.0f }));
            configureFixedChild(*child);

            StackLayoutEngine engine;
            LayoutContext context(&container);
            engine.Arrange(context, Rect{ 0.0f, 0.0f, 200.0f, 100.0f });

            CUI_EXPECT_NEAR(80.0f, child->GetActualLocationDip().x, 0.0001f);
            CUI_EXPECT_NEAR(0.0f, child->GetActualLocationDip().y, 0.0001f);
            CUI_EXPECT_NEAR(40.0f, child->GetActualSizeDip().width, 0.0001f);
            CUI_EXPECT_NEAR(10.0f, child->GetActualSizeDip().height, 0.0001f);
        }

        {
            Control container;
            auto* child = container.AdoptVisualChild(
                new FractionalMeasureControl(Size{ 12.0f, 8.0f }));
            configureFixedChild(*child);

            StackLayoutEngine engine;
            engine.SetOrientation(Orientation::Horizontal);
            LayoutContext context(&container);
            engine.Arrange(context, Rect{ 0.0f, 0.0f, 200.0f, 100.0f });

            CUI_EXPECT_NEAR(0.0f, child->GetActualLocationDip().x, 0.0001f);
            CUI_EXPECT_NEAR(45.0f, child->GetActualLocationDip().y, 0.0001f);
            CUI_EXPECT_NEAR(40.0f, child->GetActualSizeDip().width, 0.0001f);
            CUI_EXPECT_NEAR(10.0f, child->GetActualSizeDip().height, 0.0001f);
        }

        {
            Control container;
            auto* child = container.AdoptVisualChild(
                new FractionalMeasureControl(Size{ 12.0f, 8.0f }));
            configureFixedChild(*child);

            GridLayoutEngine engine;
            engine.AddColumn(ColumnDefinition(GridLength::Pixels(200.0f)));
            engine.AddRow(RowDefinition(GridLength::Pixels(100.0f)));
            LayoutContext context(&container);
            engine.Arrange(context, Rect{ 0.0f, 0.0f, 200.0f, 100.0f });

            CUI_EXPECT_NEAR(80.0f, child->GetActualLocationDip().x, 0.0001f);
            CUI_EXPECT_NEAR(45.0f, child->GetActualLocationDip().y, 0.0001f);
            CUI_EXPECT_NEAR(40.0f, child->GetActualSizeDip().width, 0.0001f);
            CUI_EXPECT_NEAR(10.0f, child->GetActualSizeDip().height, 0.0001f);
        }

        {
            Control container;
            auto* child = container.AdoptVisualChild(
                new FractionalMeasureControl(Size{ 12.0f, 8.0f }));
            configureFixedChild(*child);

            DockLayoutEngine engine;
            LayoutContext context(&container);
            engine.Arrange(context, Rect{ 0.0f, 0.0f, 200.0f, 100.0f });

            CUI_EXPECT_NEAR(80.0f, child->GetActualLocationDip().x, 0.0001f);
            CUI_EXPECT_NEAR(45.0f, child->GetActualLocationDip().y, 0.0001f);
            CUI_EXPECT_NEAR(40.0f, child->GetActualSizeDip().width, 0.0001f);
            CUI_EXPECT_NEAR(10.0f, child->GetActualSizeDip().height, 0.0001f);
        }

        {
            ContentControl host;
            auto childOwner = std::make_unique<FractionalMeasureControl>(
                Size{ 12.0f, 8.0f });
            auto* child = childOwner.get();
            configureFixedChild(*child);
            CUI_EXPECT_TRUE(host.SetVisualContent(std::move(childOwner)) != nullptr);

            host.Arrange(Rect{ 0.0f, 0.0f, 200.0f, 100.0f });
            host.UpdateLayout();

            CUI_EXPECT_NEAR(80.0f, child->GetActualLocationDip().x, 0.0001f);
            CUI_EXPECT_NEAR(45.0f, child->GetActualLocationDip().y, 0.0001f);
            CUI_EXPECT_NEAR(40.0f, child->GetActualSizeDip().width, 0.0001f);
            CUI_EXPECT_NEAR(10.0f, child->GetActualSizeDip().height, 0.0001f);
        }
    });

