    runner.Add("Grid redistributes bounded Pixel and Star tracks", []
    {
        using namespace cui::core;

        Control container;
        auto* fixedChild = container.AdoptVisualChild(new FractionalMeasureControl(Size{ 1.0f, 1.0f }));
        auto* flexibleChild = container.AdoptVisualChild(new FractionalMeasureControl(Size{ 1.0f, 1.0f }));
        auto* cappedChild = container.AdoptVisualChild(new FractionalMeasureControl(Size{ 1.0f, 1.0f }));
        Grid::SetColumn(*fixedChild, 0);
        Grid::SetColumn(*flexibleChild, 1);
        Grid::SetColumn(*cappedChild, 2);
        fixedChild->HorizontalAlignment = HorizontalAlignment::Stretch;
        flexibleChild->HorizontalAlignment = HorizontalAlignment::Stretch;
        cappedChild->HorizontalAlignment = HorizontalAlignment::Stretch;
        fixedChild->VerticalAlignment = VerticalAlignment::Stretch;
        flexibleChild->VerticalAlignment = VerticalAlignment::Stretch;
        cappedChild->VerticalAlignment = VerticalAlignment::Stretch;

        GridLayoutEngine engine;
        engine.AddColumn(ColumnDefinition(GridLength::Pixels(50.0f)));
        engine.AddColumn(ColumnDefinition(GridLength::Star(1.0f), 80.0f));
        engine.AddColumn(ColumnDefinition(GridLength::Star(1.0f), 0.0f, 40.0f));
        engine.AddRow(RowDefinition(GridLength::Pixels(20.0f)));

        LayoutContext context(&container);
        const auto desired = engine.Measure(context, Constraints{ Size{ 200.0f, 20.0f } });
        CUI_EXPECT_NEAR(200.0f, desired.width, 0.0001f);
        engine.Arrange(context, Rect{ 0.0f, 0.0f, 200.0f, 20.0f });

        CUI_EXPECT_NEAR(50.0f, fixedChild->GetActualSizeDip().width, 0.0001f);
        CUI_EXPECT_NEAR(110.0f, flexibleChild->GetActualSizeDip().width, 0.0001f);
        CUI_EXPECT_NEAR(40.0f, cappedChild->GetActualSizeDip().width, 0.0001f);
        CUI_EXPECT_NEAR(50.0f, flexibleChild->GetActualLocationDip().x, 0.0001f);
        CUI_EXPECT_NEAR(160.0f, cappedChild->GetActualLocationDip().x, 0.0001f);
    });

