	runner.Add("RoutedCommand class bindings prefer exact XAML QName before native host closure", []
	{
		std::wstring error;
		auto exactSchema = CreateDeclarativeTestSchema(
			{}, &error, L"ExactCommandCard");
		auto peerSchema = CreateDeclarativeTestSchema(
			{}, &error, L"PeerCommandCard");
		CUI_EXPECT_TRUE(exactSchema && peerSchema);
		Panel exactTarget;
		Panel peerTarget;
		CUI_EXPECT_TRUE(cui::framework::XamlAccess::SetTypeDescriptor(
			exactTarget, exactSchema, &error));
		CUI_EXPECT_TRUE(cui::framework::XamlAccess::SetTypeDescriptor(
			peerTarget, peerSchema, &error));

		const RoutedCommand command(L"Core.ClassBinding");
		int exactCan = 0;
		int exactExecute = 0;
		int nativeCan = 0;
		int nativeExecute = 0;
		CommandBinding exact;
		exact.Command = command;
		exact.CanExecute = [&](Control*, CanExecuteRoutedEventArgs& args)
		{
			++exactCan;
			args.CanExecute = true;
		};
		exact.Executed = [&](Control*, ExecutedRoutedEventArgs&)
		{
			++exactExecute;
		};
		auto exactLifetime =
			RoutedCommandManager::RegisterClassCommandBinding(
				exactSchema->TypeId(), std::move(exact));

		CommandBinding native;
		native.Command = command;
		native.CanExecute = [&](Control*, CanExecuteRoutedEventArgs& args)
		{
			++nativeCan;
			args.CanExecute = true;
		};
		native.Executed = [&](Control*, ExecutedRoutedEventArgs&)
		{
			++nativeExecute;
		};
		auto nativeLifetime =
			RoutedCommandManager::RegisterClassCommandBinding(
				UIClass::UI_Panel, std::move(native));
		CUI_EXPECT_TRUE(exactLifetime.Connected());
		CUI_EXPECT_TRUE(nativeLifetime.Connected());

		const auto exactResult = RoutedCommandManager::ExecuteCommand(
			command, exactTarget);
		CUI_EXPECT_TRUE(exactResult.Executed);
		CUI_EXPECT_EQ(1, exactCan);
		CUI_EXPECT_EQ(1, exactExecute);
		CUI_EXPECT_EQ(0, nativeCan);
		CUI_EXPECT_EQ(0, nativeExecute);

		const auto peerResult = RoutedCommandManager::ExecuteCommand(
			command, peerTarget);
		CUI_EXPECT_TRUE(peerResult.Executed);
		CUI_EXPECT_EQ(1, nativeCan);
		CUI_EXPECT_EQ(1, nativeExecute);

		exactLifetime.Disconnect();
		CUI_EXPECT_TRUE(RoutedCommandManager::Execute(command, exactTarget));
		CUI_EXPECT_EQ(2, nativeCan);
		CUI_EXPECT_EQ(2, nativeExecute);
	});

