	runner.Add("RoutedCommand requery is coalesced per Window and observers use focused target", []
	{
		Window form; ConfigureTestControl(form, L"Command domain");
		SetDeclaredWindowGeometry(form, 0.0f, 0.0f, 360.0f, 160.0f);
		std::unique_ptr<Control> content = MakeTestControl<Panel>();
		auto* panel = dynamic_cast<Panel*>(content.get());
		auto* source = panel ? AddTestVisual<Button>(*panel, L"Command source", 0, 0) : nullptr;
		auto* target = panel ? AddTestVisual<Button>(*panel, L"Command target", 100, 0) : nullptr;
		CUI_EXPECT_TRUE(panel && source && target);
		CUI_EXPECT_TRUE(form.TrySetVisualContent(content));
		if (!source || !target) return;
		target->Focusable = true;
		form.SetKeyboardFocus(target, false);

		bool allowed = true;
		int canCount = 0;
		CommandBinding binding;
		binding.Command = RoutedCommand(L"Core.Observed");
		binding.CanExecute = [&](Control*, CanExecuteRoutedEventArgs& args)
		{
			++canCount;
			CUI_EXPECT_TRUE(args.OriginalSource == target);
			args.CanExecute = allowed;
		};
		auto bindingLifetime = form.AddCommandBinding(std::move(binding));
		CUI_EXPECT_TRUE(bindingLifetime.Connected());
		cui::PumpUIThreadCallbacks();

		std::vector<RoutedCommandCanExecuteResult> observed;
		auto observer = RoutedCommandManager::ObserveCanExecute(
			*source,
			RoutedCommandSourceQuery{ RoutedCommand(L"Core.Observed"), {}, nullptr },
			[&](Control& sender, const RoutedCommandCanExecuteResult& result)
			{
				CUI_EXPECT_TRUE(&sender == source);
				observed.push_back(result);
			});
		CUI_EXPECT_TRUE(observer.Connected());
		CUI_EXPECT_EQ(1ULL, observed.size());
		CUI_EXPECT_TRUE(observed.back().CanExecute);
		CUI_EXPECT_TRUE(observed.back().Target == target);
		const auto baselineGeneration = observed.back().RequeryGeneration;

		int suggestedCount = 0;
		std::uint64_t suggestedGeneration = 0;
		auto suggested = RoutedCommandManager::SubscribeRequerySuggested(
			*source, [&](const RoutedCommandRequeryEventArgs& args)
			{
				++suggestedCount;
				CUI_EXPECT_TRUE(args.Scope == &form);
				suggestedGeneration = args.Generation;
			});
		allowed = false;
		CUI_EXPECT_TRUE(RoutedCommandManager::InvalidateRequerySuggested(*source));
		CUI_EXPECT_TRUE(RoutedCommandManager::InvalidateRequerySuggested(*source));
		CUI_EXPECT_EQ(1ULL, observed.size());
		cui::PumpUIThreadCallbacks();
		CUI_EXPECT_EQ(2ULL, observed.size());
		CUI_EXPECT_FALSE(observed.back().CanExecute);
		CUI_EXPECT_TRUE(observed.back().Target == target);
		CUI_EXPECT_EQ(baselineGeneration + 1,
			observed.back().RequeryGeneration);
		CUI_EXPECT_EQ(1, suggestedCount);
		CUI_EXPECT_EQ(observed.back().RequeryGeneration, suggestedGeneration);
		CUI_EXPECT_TRUE(canCount >= 2);

		{
			Window shortLived; ConfigureTestControl(shortLived, L"Queued command domain");
			SetDeclaredWindowGeometry(shortLived, 0.0f, 0.0f, 120.0f, 80.0f);
			CUI_EXPECT_TRUE(RoutedCommandManager::InvalidateRequerySuggested(
				shortLived));
		}
		cui::PumpUIThreadCallbacks();
	});

	runner.Add("Command CanExecute coerces effective IsEnabled without replacing authored state", []
	{
		Panel parent;
		auto* source = AddTestVisual<Button>(parent, L"Command-gated", 0, 0);
		CUI_EXPECT_TRUE(source != nullptr);
		if (!source) return;

		source->IsEnabled = false;
		CUI_EXPECT_EQ(DependencyPropertyValueSource::Local,
			source->GetPropertyValueSource(L"IsEnabled"));
		source->SetCommandCanExecuteState(true);
		CUI_EXPECT_FALSE(source->IsLocallyEnabled());
		CUI_EXPECT_FALSE(source->IsEnabled);
		CUI_EXPECT_FALSE(source->IsEffectivelyEnabled());

		source->IsEnabled = true;
		CUI_EXPECT_EQ(DependencyPropertyValueSource::Local,
			source->GetPropertyValueSource(L"IsEnabled"));
		source->SetCommandCanExecuteState(false);
		CUI_EXPECT_TRUE(source->IsLocallyEnabled());
		CUI_EXPECT_FALSE(source->IsEnabled);
		CUI_EXPECT_FALSE(source->IsEffectivelyEnabled());
		source->ClearCommandCanExecuteState();
		CUI_EXPECT_TRUE(source->IsEnabled);
		CUI_EXPECT_TRUE(source->IsEffectivelyEnabled());

		parent.IsEnabled = false;
		source->SetCommandCanExecuteState(true);
		CUI_EXPECT_TRUE(source->IsLocallyEnabled());
		CUI_EXPECT_FALSE(source->IsEnabled);
		CUI_EXPECT_FALSE(source->IsEffectivelyEnabled());
		parent.IsEnabled = true;
		CUI_EXPECT_TRUE(source->IsEffectivelyEnabled());

		Window window; ConfigureTestControl(window, L"Enabled root");
		SetDeclaredWindowGeometry(window, 0.0f, 0.0f, 160.0f, 90.0f);
		auto content = MakeTestControl<Panel>();
		auto* descendant = AddTestVisual<Button>(*content, L"Descendant", 0, 0);
		CUI_EXPECT_TRUE(descendant != nullptr);
		window.SetVisualContent(std::move(content));
		int descendantEnabledChanges = 0;
		auto enabledChanged = descendant->OnPropertyValueChanged.Subscribe(
			[&](DependencyObject*, const DependencyPropertyChangedEventArgs& args)
			{
				if (args.PropertyName == L"IsEnabled")
					++descendantEnabledChanges;
			});
		window.IsEnabled = false;
		CUI_EXPECT_FALSE(window.IsEffectivelyEnabled());
		CUI_EXPECT_FALSE(descendant->IsEffectivelyEnabled());
		CUI_EXPECT_FALSE(::IsWindowEnabled(window.GetHandle()) != FALSE);
		CUI_EXPECT_EQ(1, descendantEnabledChanges);
		CUI_EXPECT_TRUE(window.TrySetValue(L"IsEnabled", BindingValue(true)));
		CUI_EXPECT_TRUE(window.IsEffectivelyEnabled());
		CUI_EXPECT_TRUE(descendant->IsEffectivelyEnabled());
		CUI_EXPECT_TRUE(::IsWindowEnabled(window.GetHandle()) != FALSE);
		CUI_EXPECT_EQ(2, descendantEnabledChanges);
	});

	runner.Add("SizeChanged publishes one direct WPF old-new size payload", []
	{
		using namespace cui::core;

		Control target;
		std::vector<std::pair<Size, Size>> observedSizes;
		std::vector<std::pair<bool, bool>> observedAxes;
		auto changed = target.SizeChanged.Subscribe(
			[&](Control* sender, SizeChangedEventArgs& args)
			{
				CUI_EXPECT_TRUE(sender == &target);
				CUI_EXPECT_TRUE(args.OriginalSource == &target);
				CUI_EXPECT_TRUE(args.Source == &target);
				CUI_EXPECT_TRUE(args.CurrentTarget == &target);
				CUI_EXPECT_TRUE(args.EventId == RoutedEventId::SizeChanged);
				CUI_EXPECT_TRUE(
					args.RoutingStrategy == RoutedEventRoutingStrategy::Direct);
				observedSizes.emplace_back(args.PreviousSize, args.NewSize);
				observedAxes.emplace_back(
					args.WidthChanged, args.HeightChanged);
			});

		target.Arrange(Rect{ 3.0f, 4.0f, 80.0f, 25.0f });
		CUI_EXPECT_EQ(1ULL, observedSizes.size());
		CUI_EXPECT_TRUE(observedSizes[0]
			== (std::pair<Size, Size>{ Size{}, Size{ 80.0f, 25.0f } }));
		CUI_EXPECT_TRUE(observedAxes[0]
			== (std::pair<bool, bool>{ true, true }));

		// A location-only arrange is not a SizeChanged transaction.
		target.Arrange(Rect{ 9.0f, 12.0f, 80.0f, 25.0f });
		CUI_EXPECT_EQ(1ULL, observedSizes.size());

		target.Arrange(Rect{ 9.0f, 12.0f, 95.0f, 25.0f });
		CUI_EXPECT_EQ(2ULL, observedSizes.size());
		CUI_EXPECT_TRUE(observedSizes[1] == (std::pair<Size, Size>{
			Size{ 80.0f, 25.0f }, Size{ 95.0f, 25.0f } }));
		CUI_EXPECT_TRUE(observedAxes[1]
			== (std::pair<bool, bool>{ true, false }));
	});

	runner.Add("Visibility keeps Hidden in layout and propagates effective IsVisible", []
	{
		using namespace cui::core;

		Panel parent;
		auto* child = AddTestVisual<Button>(parent, L"Child", 0, 0);
		CUI_EXPECT_TRUE(child != nullptr);
		if (!child) return;
		CUI_EXPECT_TRUE(parent.IsVisible);
		CUI_EXPECT_TRUE(child->IsVisible);
		CUI_EXPECT_TRUE(child->Visibility == Visibility::Visible);

		std::vector<std::pair<bool, bool>> changes;
		auto changed = child->IsVisibleChanged.Subscribe(
			[&](DependencyObject* sender,
				const DependencyPropertyChangedEventArgs& args)
			{
				CUI_EXPECT_TRUE(sender == child);
				bool oldValue = false;
				bool newValue = false;
				CUI_EXPECT_TRUE(args.OldValue.TryGetBool(oldValue));
				CUI_EXPECT_TRUE(args.NewValue.TryGetBool(newValue));
				changes.emplace_back(oldValue, newValue);
			});
		parent.Visibility = Visibility::Hidden;
		CUI_EXPECT_EQ(DependencyPropertyValueSource::Local,
			parent.GetPropertyValueSource(L"Visibility"));
		CUI_EXPECT_FALSE(parent.IsVisible);
		CUI_EXPECT_FALSE(child->IsVisible);
		CUI_EXPECT_TRUE(child->Visibility == Visibility::Visible);
		CUI_EXPECT_EQ(1ULL, changes.size());
		CUI_EXPECT_TRUE(changes.back()
			== (std::pair<bool, bool>{ true, false }));
		parent.Visibility = Visibility::Visible;
		CUI_EXPECT_TRUE(child->IsVisible);
		CUI_EXPECT_EQ(2ULL, changes.size());
		CUI_EXPECT_TRUE(changes.back()
			== (std::pair<bool, bool>{ false, true }));
		CUI_EXPECT_FALSE(child->TrySetValue(
			L"IsVisible", BindingValue(false)));

		Control layoutRoot;
		auto* visible = layoutRoot.AdoptVisualChild(
			new FractionalMeasureControl(Size{ 40.0f, 10.0f }));
		auto* hidden = layoutRoot.AdoptVisualChild(
			new FractionalMeasureControl(Size{ 30.0f, 20.0f }));
		auto* collapsed = layoutRoot.AdoptVisualChild(
			new FractionalMeasureControl(Size{ 100.0f, 100.0f }));
		hidden->Visibility = Visibility::Hidden;
		collapsed->Visibility = Visibility::Collapsed;
		StackLayoutEngine engine;
		LayoutContext context(&layoutRoot);
		const auto desired = engine.Measure(
			context, Constraints::Unbounded());
		CUI_EXPECT_NEAR(40.0f, desired.width, 0.0001f);
		CUI_EXPECT_NEAR(30.0f, desired.height, 0.0001f);
		engine.Arrange(context, Rect{ 0.0f, 0.0f, 100.0f, 80.0f });
		CUI_EXPECT_TRUE(visible->IsVisible);
		CUI_EXPECT_FALSE(hidden->IsVisible);
		CUI_EXPECT_FALSE(collapsed->IsVisible);
		CUI_EXPECT_NEAR(10.0f,
			hidden->GetActualLocationDip().y, 0.0001f);
		CUI_EXPECT_NEAR(20.0f,
			hidden->GetActualSizeDip().height, 0.0001f);
	});

