	runner.Add("Runtime CommandTarget materialization preserves namescopes and pending Window identity", []
	{
		const std::string xaml = R"XAML(<Window xmlns="urn:cui"
  xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
  xmlns:local="urn:cui:runtime-command-targets"
  x:Name="RuntimeCommandWindow" Width="640" Height="360">
  <Window.Resources>
    <ComponentDefinition x:Key="local:TargetSurface" BaseType="Canvas">
      <ComponentDefinition.Template>
        <Canvas x:Name="templateRoot">
          <Canvas x:Name="partTarget" />
          <Button x:Name="partSource"
            CommandTarget="{x:Reference partTarget}" />
        </Canvas>
      </ComponentDefinition.Template>
    </ComponentDefinition>
  </Window.Resources>
  <Canvas x:Name="root" DesignId="1">
    <Canvas x:Name="routeTarget" DesignId="2" />
    <Button x:Name="directSource" DesignId="3"
      CommandTarget="{x:Reference routeTarget}">
      <Button.InputBindings>
        <KeyBinding Command="Runtime.WindowTarget" Gesture="F7"
          CommandTarget="{x:Reference RuntimeCommandWindow}" />
      </Button.InputBindings>
    </Button>
    <Button x:Name="windowSource" DesignId="4"
      CommandTarget="{x:Reference RuntimeCommandWindow}" />
    <Menu x:Name="mainMenu" DesignId="5">
      <Menu.Items>
        <MenuItem Header="Open" CommandTarget="{x:Reference routeTarget}">
          <MenuItem.Items>
            <MenuItem Header="Window route"
              CommandTarget="{x:Reference RuntimeCommandWindow}" />
          </MenuItem.Items>
        </MenuItem>
      </Menu.Items>
    </Menu>
    <local:TargetSurface x:Name="surface" DesignId="6" />
  </Canvas>
</Window>)XAML";

		DesignerModel::DesignDocument document;
		std::wstring error;
		if (!DesignerModel::XamlDocumentParser::FromXaml(
			xaml, document, &error))
			throw std::runtime_error(Convert::UnicodeToUtf8(error));
		CuiRuntime::XamlObjectTree tree;
		if (!CuiRuntime::XamlObjectMaterializer::Materialize(
			document, tree, {}, &error))
			throw std::runtime_error(Convert::UnicodeToUtf8(error));
		auto materialized = [&](const std::wstring& name) -> Control*
		{
			const auto found = std::find_if(
				tree.Controls.begin(), tree.Controls.end(),
				[&](const auto& record)
				{
					return record && record->Name == name;
				});
			return found == tree.Controls.end()
				? nullptr : (*found)->ControlInstance;
		};
		auto* routeTarget = materialized(L"routeTarget");
		auto* directSource = dynamic_cast<Button*>(
			materialized(L"directSource"));
		auto* windowSource = dynamic_cast<Button*>(
			materialized(L"windowSource"));
		auto* menu = dynamic_cast<Menu*>(materialized(L"mainMenu"));
		auto* surface = materialized(L"surface");
		auto* templateSource = surface
			? dynamic_cast<Button*>(
				surface->FindDeclarativeTemplatePart(L"partSource")) : nullptr;
		auto* templateTarget = surface
			? surface->FindDeclarativeTemplatePart(L"partTarget") : nullptr;
		auto* topItem = menu ? menu->GetItem(0) : nullptr;
		auto* childItem = topItem ? topItem->GetSubItem(0) : nullptr;
		auto inputTarget = [](Control* source)
		{
			if (!source || source->GetInputBindings().empty())
				return ControlWeakReference{};
			return std::visit([](const auto& binding)
			{
				return binding.CommandTarget;
			}, source->GetInputBindings().front());
		};
		CUI_EXPECT_TRUE(routeTarget && directSource && windowSource
			&& menu && topItem && childItem && templateSource && templateTarget);
		CUI_EXPECT_EQ(5ULL, tree.CommandTargets.size());
		CUI_EXPECT_EQ(1ULL, tree.InputBindingTargets.size());
		CUI_EXPECT_TRUE(directSource
			&& directSource->CommandTarget == routeTarget);
		CUI_EXPECT_TRUE(windowSource
			&& windowSource->HasAuthoredCommandTarget());
		CUI_EXPECT_TRUE(windowSource && windowSource->CommandTarget == nullptr);
		CUI_EXPECT_TRUE(topItem && topItem->CommandTarget == routeTarget);
		CUI_EXPECT_TRUE(childItem && childItem->HasAuthoredCommandTarget());
		CUI_EXPECT_TRUE(childItem && childItem->CommandTarget == nullptr);
		CUI_EXPECT_TRUE(templateSource
			&& templateSource->CommandTarget == templateTarget);
		CUI_EXPECT_TRUE(inputTarget(directSource).HasValue());
		CUI_EXPECT_TRUE(inputTarget(directSource).Get() == nullptr);

		DesignerModel::RuntimeDocument runtime;
		if (!DesignerModel::RuntimeDocumentLoader::Load(
			document, runtime, {}, &error))
			throw std::runtime_error(Convert::UnicodeToUtf8(error));
		auto* runtimeTarget = runtime.FindControlByName(L"routeTarget");
		auto* runtimeDirect = runtime.FindControlByDesignId<Button>(3);
		auto* runtimeWindow = runtime.FindControlByName(L"windowSource");
		auto* runtimeSurface = runtime.FindControlByName(L"surface");
		auto* runtimeTemplateSource = runtimeSurface
			? dynamic_cast<Button*>(runtimeSurface->FindDeclarativeTemplatePart(
				L"partSource")) : nullptr;
		auto* runtimeTemplateTarget = runtimeSurface
			? runtimeSurface->FindDeclarativeTemplatePart(L"partTarget") : nullptr;
		CUI_EXPECT_TRUE(runtimeDirect
			&& runtimeDirect->CommandTarget == runtimeTarget);
		auto* runtimeWindowButton = dynamic_cast<Button*>(runtimeWindow);
		CUI_EXPECT_TRUE(runtimeWindowButton
			&& runtimeWindowButton->HasAuthoredCommandTarget());
		CUI_EXPECT_TRUE(runtimeWindowButton
			&& runtimeWindowButton->CommandTarget == nullptr);
		CUI_EXPECT_TRUE(runtimeTemplateSource
			&& runtimeTemplateSource->CommandTarget == runtimeTemplateTarget);
		CUI_EXPECT_TRUE(inputTarget(runtimeDirect).HasValue());
		CUI_EXPECT_TRUE(inputTarget(runtimeDirect).Get() == nullptr);

		Window detachWindow; ConfigureTestControl(detachWindow, L"Detach command target");
		SetDeclaredWindowGeometry(detachWindow, 0.0f, 0.0f, 640.0f, 360.0f);
		CUI_EXPECT_TRUE(runtime.ApplyWindowProperties(detachWindow, &error));
		CUI_EXPECT_TRUE(runtimeWindowButton
			&& runtimeWindowButton->CommandTarget == &detachWindow);
		CUI_EXPECT_TRUE(inputTarget(runtimeDirect).Get() == &detachWindow);
		auto released = runtime.ReleaseContentRoot();
		CUI_EXPECT_TRUE(released != nullptr);
		CUI_EXPECT_TRUE(runtimeWindowButton
			&& runtimeWindowButton->HasAuthoredCommandTarget());
		CUI_EXPECT_TRUE(runtimeWindowButton
			&& runtimeWindowButton->CommandTarget == nullptr);
		CUI_EXPECT_TRUE(inputTarget(runtimeDirect).HasValue());
		CUI_EXPECT_TRUE(inputTarget(runtimeDirect).Get() == nullptr);
	});

	runner.Add("Runtime CommandTarget Window attach and topology reload roll back atomically", []
	{
		class TransactionalContentHost final
			: public DesignerModel::RuntimeDocumentContentHost
		{
		public:
			std::unique_ptr<Control> Content;
			bool RejectInitial = false;
			bool RejectReplacement = false;

			bool DetachContent(
				Control* content,
				std::unique_ptr<Control>& output,
				std::wstring* outError) override
			{
				if (!Content || Content.get() != content || output)
				{
					if (outError) *outError = L"测试宿主无法分离 Content。";
					return false;
				}
				output = std::move(Content);
				return true;
			}

			bool AttachContent(
				std::unique_ptr<Control>& content,
				DesignerModel::RuntimeContentHostAttachMode mode,
				std::wstring* outError) override
			{
				if ((mode == DesignerModel::RuntimeContentHostAttachMode::Initial
						&& RejectInitial)
					|| (mode == DesignerModel::RuntimeContentHostAttachMode::Replacement
						&& RejectReplacement))
				{
					if (outError) *outError = L"测试宿主拒绝 Content。";
					return false;
				}
				if (Content || !content)
				{
					if (outError) *outError = L"测试宿主 Content 状态无效。";
					return false;
				}
				Content = std::move(content);
				return true;
			}
		};

		const std::string xaml = R"XAML(<Window xmlns="urn:cui"
  xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
  x:Name="TransactionalCommandWindow" Width="480" Height="260">
  <Canvas x:Name="root" DesignId="1">
    <Canvas x:Name="routeTarget" DesignId="2" />
    <Button x:Name="windowSource" DesignId="3"
      CommandTarget="{x:Reference TransactionalCommandWindow}" />
    <Button x:Name="stableSibling" DesignId="4">
      <Button.InputBindings>
        <KeyBinding Command="Runtime.ReloadTarget" Gesture="F8"
          CommandTarget="{x:Reference TransactionalCommandWindow}" />
      </Button.InputBindings>
    </Button>
  </Canvas>
</Window>)XAML";
		DesignerModel::DesignDocument document;
		std::wstring error;
		if (!DesignerModel::XamlDocumentParser::FromXaml(
			xaml, document, &error))
			throw std::runtime_error(Convert::UnicodeToUtf8(error));
		DesignerModel::RuntimeDocument runtime;
		if (!DesignerModel::RuntimeDocumentLoader::Load(
			document, runtime, {}, &error))
			throw std::runtime_error(Convert::UnicodeToUtf8(error));
		auto inputTarget = [](Control* source)
		{
			if (!source || source->GetInputBindings().empty())
				return ControlWeakReference{};
			return std::visit([](const auto& binding)
			{
				return binding.CommandTarget;
			}, source->GetInputBindings().front());
		};
		auto* originalSource = runtime.FindControlByDesignId<Button>(3);
		auto* originalInputSource =
			runtime.FindControlByDesignId<Button>(4);
		CUI_EXPECT_TRUE(originalSource != nullptr);
		CUI_EXPECT_TRUE(originalInputSource != nullptr);
		CUI_EXPECT_TRUE(originalSource
			&& originalSource->HasAuthoredCommandTarget());
		CUI_EXPECT_TRUE(originalSource
			&& originalSource->CommandTarget == nullptr);
		CUI_EXPECT_TRUE(inputTarget(originalInputSource).HasValue());
		CUI_EXPECT_TRUE(inputTarget(originalInputSource).Get() == nullptr);

		Window window; ConfigureTestControl(window, L"Transactional command target");
		SetDeclaredWindowGeometry(window, 0.0f, 0.0f, 480.0f, 260.0f);
		auto host = std::make_shared<TransactionalContentHost>();
		host->RejectInitial = true;
		CUI_EXPECT_FALSE(runtime.AttachToWindow(
			window, host, {}, &error));
		CUI_EXPECT_TRUE(host->Content == nullptr);
		CUI_EXPECT_TRUE(originalSource
			&& originalSource->HasAuthoredCommandTarget());
		CUI_EXPECT_TRUE(originalSource
			&& originalSource->CommandTarget == nullptr);
		CUI_EXPECT_TRUE(inputTarget(originalInputSource).HasValue());
		CUI_EXPECT_TRUE(inputTarget(originalInputSource).Get() == nullptr);

		host->RejectInitial = false;
		CUI_EXPECT_TRUE(runtime.AttachToWindow(
			window, host, {}, &error));
		CUI_EXPECT_TRUE(host->Content.get() == runtime.ContentRoot());
		CUI_EXPECT_TRUE(originalSource
			&& originalSource->CommandTarget == &window);
		CUI_EXPECT_TRUE(inputTarget(originalInputSource).Get() == &window);

		auto changed = document;
		auto sourceNode = std::find_if(
			changed.Nodes.begin(), changed.Nodes.end(),
			[](const auto& node) { return node.Id == 3; });
		CUI_EXPECT_TRUE(sourceNode != changed.Nodes.end());
		if (sourceNode == changed.Nodes.end()) return;
		sourceNode->Structure.CommandTarget = L"routeTarget";
		auto inputSourceNode = std::find_if(
			changed.Nodes.begin(), changed.Nodes.end(),
			[](const auto& node) { return node.Id == 4; });
		CUI_EXPECT_TRUE(inputSourceNode != changed.Nodes.end());
		if (inputSourceNode == changed.Nodes.end()
			|| inputSourceNode->InputBindings.empty()) return;
		inputSourceNode->InputBindings.front().CommandTarget =
			L"routeTarget";
		DesignerModel::RuntimeDocumentReloadMode mode =
			DesignerModel::RuntimeDocumentReloadMode::Unchanged;
		host->RejectReplacement = true;
		CUI_EXPECT_FALSE(DesignerModel::RuntimeDocumentLoader::Reload(
			changed, runtime, {}, &mode, &error));
		CUI_EXPECT_TRUE(host->Content.get() == runtime.ContentRoot());
		CUI_EXPECT_TRUE(runtime.FindControlByDesignId<Button>(3)
			== originalSource);
		CUI_EXPECT_TRUE(runtime.FindControlByDesignId<Button>(4)
			== originalInputSource);
		CUI_EXPECT_TRUE(originalSource
			&& originalSource->CommandTarget == &window);
		CUI_EXPECT_TRUE(inputTarget(originalInputSource).Get() == &window);

		host->RejectReplacement = false;
		CUI_EXPECT_TRUE(DesignerModel::RuntimeDocumentLoader::Reload(
			changed, runtime, {}, &mode, &error));
		CUI_EXPECT_EQ(DesignerModel::RuntimeDocumentReloadMode::Recomposed, mode);
		auto* reloadedSource = runtime.FindControlByDesignId<Button>(3);
		auto* reloadedInputSource =
			runtime.FindControlByDesignId<Button>(4);
		auto* reloadedTarget = runtime.FindControlByName(L"routeTarget");
		CUI_EXPECT_TRUE(reloadedSource && reloadedInputSource && reloadedTarget);
		CUI_EXPECT_TRUE(reloadedSource
			&& reloadedSource->CommandTarget == reloadedTarget);
		CUI_EXPECT_TRUE(inputTarget(reloadedInputSource).Get()
			== reloadedTarget);
	});

	runner.Add("Static generation wires authored ICommandSource targets after namescope creation", []
	{
		const std::string xaml = R"XAML(<Window xmlns="urn:cui"
  xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
  x:Name="GeneratedCommandTargetWindow" Width="640" Height="360">
  <Canvas x:Name="root" DesignId="1">
    <Button x:Name="directSource" DesignId="2"
      CommandTarget="{x:Reference routeTarget}" />
    <Button x:Name="windowSource" DesignId="3"
      CommandTarget="{x:Reference GeneratedCommandTargetWindow}" />
    <Canvas x:Name="routeTarget" DesignId="4" />
    <Menu x:Name="mainMenu" DesignId="5">
      <Menu.Items>
        <MenuItem Header="Open"
          CommandTarget="{x:Reference routeTarget}">
          <MenuItem.Items>
            <MenuItem Header="Window route"
              CommandTarget="{x:Reference GeneratedCommandTargetWindow}" />
          </MenuItem.Items>
        </MenuItem>
      </Menu.Items>
    </Menu>
  </Canvas>
</Window>)XAML";

		DesignerModel::DesignDocument document;
		std::wstring error;
		CUI_EXPECT_TRUE(DesignerModel::XamlDocumentParser::FromXaml(
			xaml, document, &error));
		CUI_EXPECT_TRUE(CodeGenerator::ValidateDocument(document, &error));
		const auto generated =
			CodeGenerator(L"GeneratedCommandTargetWindow", document).GenerateCpp();
		const auto targetCreated = generated.find(
			"routeTarget = __owned_routeTarget.get();");
		const auto directWired = generated.find(
			"directSource->CommandTarget = routeTarget;");
		CUI_EXPECT_TRUE(targetCreated != std::string::npos);
		CUI_EXPECT_TRUE(directWired != std::string::npos);
		CUI_EXPECT_TRUE(targetCreated < directWired);
		const auto countMarker = [&](std::string_view marker)
		{
			std::size_t count = 0;
			for (std::size_t at = 0;
				(at = generated.find(marker, at)) != std::string::npos;
				++count, at += marker.size()) {}
			return count;
		};
		CUI_EXPECT_EQ(2ULL,
			countMarker("->CommandTarget = routeTarget;"));
		CUI_EXPECT_EQ(2ULL,
			countMarker("->CommandTarget = this;"));
	});

	runner.Add("Designer clipboard remaps recursive authored CommandTarget references", []
	{
		DesignerModel::DesignDocument source;
		source.Window.Name = L"ClipboardCommandTargetWindow";
		source.NextStableId = 7;
		DesignerModel::DesignNode panel;
		panel.Id = 1;
		panel.Name = L"commandPanel1";
		panel.Type = UIClass::UI_Canvas;
		DesignerModel::DesignNode target;
		target.Id = 2;
		target.ParentId = panel.Id;
		target.ParentRef = panel.Name;
		target.Name = L"commandTarget1";
		target.Type = UIClass::UI_Canvas;
		DesignerModel::DesignNode button;
		button.Id = 3;
		button.ParentId = panel.Id;
		button.ParentRef = panel.Name;
		button.Name = L"commandButton1";
		button.Type = UIClass::UI_Button;
		button.Order = 1;
		button.Structure.CommandTarget = target.Name;
		DesignerModel::DesignNode menu;
		menu.Id = 4;
		menu.ParentId = panel.Id;
		menu.ParentRef = panel.Name;
		menu.Name = L"commandMenu1";
		menu.Type = UIClass::UI_ContextMenu;
		menu.Order = 2;
		DesignerModel::DesignNode top;
		top.Id = 5;
		top.ParentId = menu.Id;
		top.ParentRef = menu.Name;
		top.Name = L"commandTopItem1";
		top.Type = UIClass::UI_MenuItem;
		SetDesignNodeProperty(top, L"Header",
			DesignerStyleValueKind::String, L"Open");
		top.Structure.CommandTarget = target.Name;
		DesignerModel::DesignNode child;
		child.Id = 6;
		child.ParentId = top.Id;
		child.ParentRef = top.Name;
		child.Name = L"commandChildItem1";
		child.Type = UIClass::UI_MenuItem;
		SetDesignNodeProperty(child, L"Header",
			DesignerStyleValueKind::String, L"Inspect");
		child.Structure.CommandTarget = target.Name;
		source.Nodes = { panel, target, button, menu, top, child };

		std::wstring error;
		CUI_EXPECT_TRUE(source.ValidateCommandTargetReferences(&error));
		DesignerModel::DesignDocument fragment;
		CUI_EXPECT_TRUE(DesignerModel::DesignDocumentClipboard::Capture(
			source, { panel.Id }, fragment, &error));
		CUI_EXPECT_EQ(6ULL, fragment.Nodes.size());

		DesignerModel::DesignDocument merged;
		DesignerModel::DesignClipboardPasteResult paste;
		CUI_EXPECT_TRUE(DesignerModel::DesignDocumentClipboard::PasteAtRoot(
			source, fragment, 0, 0, merged, &paste, &error));
		auto findNode = [&](const std::wstring& name)
			-> const DesignerModel::DesignNode*
		{
			const auto found = std::find_if(
				merged.Nodes.begin(), merged.Nodes.end(),
				[&](const auto& node) { return node.Name == name; });
			return found == merged.Nodes.end() ? nullptr : &*found;
		};
		const auto* pastedButton = findNode(L"commandButton2");
		const auto* pastedMenu = findNode(L"commandMenu2");
		const auto* pastedTop = findNode(L"commandTopItem2");
		const auto* pastedChild = findNode(L"commandChildItem2");
		CUI_EXPECT_TRUE(pastedButton && pastedMenu && pastedTop && pastedChild);
		if (pastedButton && pastedMenu && pastedTop && pastedChild)
		{
			CUI_EXPECT_EQ(std::wstring(L"commandTarget2"),
				pastedButton->Structure.CommandTarget);
			CUI_EXPECT_EQ(pastedMenu->Id, pastedTop->ParentId);
			CUI_EXPECT_EQ(pastedTop->Id, pastedChild->ParentId);
			CUI_EXPECT_EQ(std::wstring(L"commandTarget2"),
				pastedTop->Structure.CommandTarget);
			CUI_EXPECT_EQ(std::wstring(L"commandTarget2"),
				pastedChild->Structure.CommandTarget);
		}
		CUI_EXPECT_TRUE(merged.ValidateCommandTargetReferences(&error));

		for (const auto isolatedId : { button.Id, menu.Id })
		{
			DesignerModel::DesignDocument rejected = fragment;
			CUI_EXPECT_FALSE(DesignerModel::DesignDocumentClipboard::Capture(
				source, { isolatedId }, rejected, &error));
			CUI_EXPECT_EQ(fragment, rejected);
			CUI_EXPECT_TRUE(error.find(L"复制范围外")
				!= std::wstring::npos);
		}
	});

