	runner.Add("RadioButton enforces WPF logical and named groups", []
	{
		Panel root;
		auto* left = AddTestVisual<Panel>(root);
		auto* right = AddTestVisual<Panel>(root);
		auto* first = AddTestVisual<RadioButton>(*left);
		auto* second = AddTestVisual<RadioButton>(*left);
		auto* namedPeer = AddTestVisual<RadioButton>(*right);
		auto* unrelated = AddTestVisual<RadioButton>(*right);

		first->IsChecked = true;
		second->IsChecked = true;
		CUI_EXPECT_FALSE(first->IsChecked);
		CUI_EXPECT_TRUE(second->IsChecked);

		first->GroupName = L"Plan";
		namedPeer->GroupName = L"Plan";
		unrelated->GroupName = L"Other";
		first->IsChecked = true;
		unrelated->IsChecked = true;
		namedPeer->IsChecked = true;
		CUI_EXPECT_FALSE(first->IsChecked);
		CUI_EXPECT_TRUE(second->IsChecked);
		CUI_EXPECT_TRUE(namedPeer->IsChecked);
		CUI_EXPECT_TRUE(unrelated->IsChecked);

		Panel independentRoot;
		auto* independent = AddTestVisual<RadioButton>(independentRoot);
		independent->GroupName = L"Plan";
		independent->IsChecked = true;
		first->IsEnabled = false;
		first->IsChecked = true;
		CUI_EXPECT_TRUE(first->IsChecked);
		CUI_EXPECT_FALSE(namedPeer->IsChecked);
		CUI_EXPECT_TRUE(independent->IsChecked);

		unrelated->GroupName = L"Plan";
		CUI_EXPECT_FALSE(first->IsChecked);
		CUI_EXPECT_TRUE(unrelated->IsChecked);
		CUI_EXPECT_EQ(DependencyPropertyValueSource::Local,
			unrelated->GetPropertyValueSource(L"GroupName"));
	});

