	runner.Add("XAML property schemas validate without target instances", []
	{
		DesignerModel::DesignDocument document;
		DesignerModel::DesignComponentDefinition component;
		component.Type.XamlNamespace = L"urn:cui:schema-tests";
		component.Type.XamlName = L"SchemaButton";
		component.BaseType = UIClass::UI_Button;
		DesignerComponentPropertyDescriptor priority;
		priority.Name = L"Priority";
		priority.DisplayName = L"Priority";
		priority.DefaultValue = { DesignerStyleValueKind::Int, L"3" };
		priority.Flags = DependencyPropertyFlags::AffectsRender;
		component.Properties.push_back(priority);
		document.Components.push_back(component);

		const auto nativeProperties =
			CuiRuntime::XamlRuntimeSchema::NativeProperties(UIClass::UI_Button);
		const auto* round = CuiRuntime::XamlRuntimeSchema::FindNativeProperty(
			UIClass::UI_Button, L"FontSize");
		CUI_EXPECT_TRUE(!nativeProperties.empty());
		CUI_EXPECT_TRUE(round != nullptr);

		CuiRuntime::XamlTypePropertySchema schema;
		std::wstring error;
		CUI_EXPECT_TRUE(CuiRuntime::XamlRuntimeSchema::BuildPropertySchema(
			UIClass::UI_Button, &document.Components.front(), document,
			schema, &error));
		CUI_EXPECT_EQ(UIClass::UI_Button, schema.NativeType);
		CUI_EXPECT_TRUE(schema.DeclarativeType != nullptr);
		CUI_EXPECT_EQ(nativeProperties.size() + 1, schema.Properties.size());
		const auto* priorityMetadata = schema.FindProperty(L"Priority");
		CUI_EXPECT_TRUE(priorityMetadata != nullptr);
		CUI_EXPECT_TRUE(priorityMetadata
			== schema.DeclarativeType->FindProperty(L"Priority"));
		CUI_EXPECT_TRUE(schema.FindProperty(L"FontSize") == round);

		DesignerStyleValue canonical;
		CUI_EXPECT_TRUE(DesignerPropertyCatalog::NormalizeStyleValue(
			*priorityMetadata,
			{ DesignerStyleValueKind::Int, L"7" }, canonical, &error));
		CUI_EXPECT_EQ(DesignerStyleValueKind::Int, canonical.Kind);
		CUI_EXPECT_EQ(std::wstring(L"7"), canonical.Text);
		DesignerStyleValue nativeDefault;
		CUI_EXPECT_TRUE(DesignerPropertyCatalog::CaptureDefaultValue(
			*round, nativeDefault, &error));
		CUI_EXPECT_EQ(DesignerStyleValueKind::Double, nativeDefault.Kind);

		DesignerStyleRule rule;
		rule.HasType = true;
		rule.Type = component.BaseType;
		rule.ComponentType = component.Type;
		rule.Setters.push_back({ L"Priority", false, L"",
			{ DesignerStyleValueKind::Int, L"8" } });
		DesignerStyleSheet sheet;
		sheet.Rules.push_back(rule);
		auto resolver = [&](const DesignerStyleRule& candidate,
			CuiRuntime::XamlTypePropertySchema& output,
			std::wstring* schemaError)
		{
			const auto* target = document.FindComponent(candidate.ComponentType);
			return target && CuiRuntime::XamlRuntimeSchema::BuildPropertySchema(
				candidate.Type, target, document, output, schemaError);
		};
		CUI_EXPECT_TRUE(
			DesignerStyleSheetUtils::ValidateAgainstRulePropertyMetadata(
				sheet, resolver, &error));
		sheet.Rules.front().Setters.front().Literal.Kind =
			DesignerStyleValueKind::String;
		CUI_EXPECT_FALSE(
			DesignerStyleSheetUtils::ValidateAgainstRulePropertyMetadata(
				sheet, resolver, &error));
		CUI_EXPECT_TRUE(error.find(L"Int") != std::wstring::npos);
	});

	runner.Add("Materializer rejects mismatched XAML identity and snapshots reject undeclared state", []
	{
		std::wstring error;
		DesignerModel::DesignDocument mismatched;
		DesignerModel::DesignNode button;
		button.Id = mismatched.AllocateNodeId();
		button.Name = L"wrongBehavior";
		button.Type = UIClass::UI_Button;
		button.XamlType = { L"urn:cui", L"Canvas" };
		mismatched.Nodes.push_back(std::move(button));
		CuiRuntime::XamlObjectTree tree;
		CUI_EXPECT_FALSE(CuiRuntime::XamlObjectMaterializer::Materialize(
			mismatched, tree, {}, &error));
		CUI_EXPECT_TRUE(error.find(L"XAML 类型") != std::wstring::npos);

		DesignerModel::DesignDocument current;
		DesignerModel::DesignNode tab;
		tab.Id = current.AllocateNodeId();
		tab.Name = L"currentTab";
		tab.Type = UIClass::UI_TabControl;
		current.Nodes.push_back(std::move(tab));

		auto snapshot = DesignerModel::DesignDocumentSerializer::ToXml(current);
		const auto version = snapshot.find("version=\"43\"");
		CUI_EXPECT_TRUE(version != std::string::npos);
		if (version != std::string::npos)
			snapshot.replace(version, std::string("version=\"43\"").size(),
				"version=\"30\"");
		DesignerModel::DesignDocument parsed;
		error.clear();
		CUI_EXPECT_FALSE(DesignerModel::DesignDocumentSerializer::FromXml(
			snapshot, parsed, &error));
		CUI_EXPECT_TRUE(error.find(L"current design snapshot")
			!= std::wstring::npos);

		auto removedState =
			DesignerModel::DesignDocumentSerializer::ToXml(current);
		const auto structure = removedState.find("<structure");
		CUI_EXPECT_TRUE(structure != std::string::npos);
		if (structure != std::string::npos)
			removedState.insert(structure, "<extra/>");
		error.clear();
		CUI_EXPECT_FALSE(DesignerModel::DesignDocumentSerializer::FromXml(
			removedState, parsed, &error));
		CUI_EXPECT_TRUE(error.find(L"unsupported child element: extra")
			!= std::wstring::npos);

		auto removedProps =
			DesignerModel::DesignDocumentSerializer::ToXml(current);
		const auto controls = removedProps.find("<controls");
		const auto properties = removedProps.find("<properties", controls);
		CUI_EXPECT_TRUE(properties != std::string::npos);
		if (properties != std::string::npos)
			removedProps.replace(properties + 1,
				std::string("properties").size(), "props");
		error.clear();
		CUI_EXPECT_FALSE(DesignerModel::DesignDocumentSerializer::FromXml(
			removedProps, parsed, &error));
		CUI_EXPECT_TRUE(error.find(L"unsupported child element: props")
			!= std::wstring::npos);
	});

	runner.Add("Runtime typed references expire safely and preserve document identity", []
	{
		auto makeDocument = [](std::string text)
		{
			DesignerModel::DesignDocument document;
			document.Window.Name = L"ReferenceWindow";
			DesignerModel::DesignNode node;
			node.Id = 17;
			node.Name = L"referenceButton";
			node.Type = UIClass::UI_Button;
			SetDesignNodeProperty(node, L"Content",
				DesignerStyleValueKind::String,
				Convert::Utf8ToUnicode(std::move(text)));
			document.Nodes.push_back(std::move(node));
			document.NextStableId = 18;
			return document;
		};

		std::wstring error;
		auto firstDocument = makeDocument("First");
		DesignerModel::RuntimeDocument runtime;
		CUI_EXPECT_TRUE(DesignerModel::RuntimeDocumentLoader::Load(
			firstDocument, runtime, {}, &error));
		auto movingDocumentReference = runtime.Reference();
		auto movingReference = runtime.ReferenceByDesignId<Button>(17);
		CUI_EXPECT_EQ(std::wstring(L"First"), movingReference->GetDisplayText());
		CUI_EXPECT_TRUE(movingDocumentReference.Get() == &runtime);
		CUI_EXPECT_TRUE(movingDocumentReference.FindControlByDesignId<Button>(17)
			== movingReference.Get());
		CUI_EXPECT_TRUE(movingDocumentReference.ReferenceByDesignId<Button>(17)
			.Get() == movingReference.Get());

		DesignerModel::RuntimeDocument moved(std::move(runtime));
		CUI_EXPECT_TRUE(movingDocumentReference.Get() == &moved);
		CUI_EXPECT_TRUE(movingReference.Get()
			== moved.FindControlByDesignId<Button>(17));
		CUI_EXPECT_TRUE(runtime.ReferenceByDesignId<Button>(17).Get() == nullptr);

		DesignerModel::RuntimeDocumentRef expiredDocumentReference;
		DesignerModel::RuntimeControlRef<Button> expiredReference;
		{
			DesignerModel::RuntimeDocument scoped;
			CUI_EXPECT_TRUE(DesignerModel::RuntimeDocumentLoader::Load(
				firstDocument, scoped, {}, &error));
			expiredDocumentReference = scoped.Reference();
			expiredReference = scoped.ReferenceByDesignId<Button>(17);
			CUI_EXPECT_TRUE(expiredDocumentReference.Get() == &scoped);
			CUI_EXPECT_TRUE(expiredReference.Get() != nullptr);
		}
		CUI_EXPECT_FALSE(static_cast<bool>(expiredDocumentReference));
		CUI_EXPECT_TRUE(expiredDocumentReference
			.FindControlByDesignId<Button>(17) == nullptr);
		CUI_EXPECT_TRUE(expiredDocumentReference
			.ReferenceByDesignId<Button>(17).Get() == nullptr);
		CUI_EXPECT_TRUE(expiredReference.Get() == nullptr);

		DesignerModel::RuntimeDocument destination;
		CUI_EXPECT_TRUE(DesignerModel::RuntimeDocumentLoader::Load(
			firstDocument, destination, {}, &error));
		auto destinationDocumentReference = destination.Reference();
		auto destinationReference =
			destination.ReferenceByDesignId<Button>(17);
		auto secondDocument = makeDocument("Second");
		DesignerModel::RuntimeDocument replacement;
		CUI_EXPECT_TRUE(DesignerModel::RuntimeDocumentLoader::Load(
			secondDocument, replacement, {}, &error));
		auto replacementDocumentReference = replacement.Reference();
		auto replacementReference =
			replacement.ReferenceByDesignId<Button>(17);
		destination = std::move(replacement);
		CUI_EXPECT_TRUE(destinationDocumentReference.Get() == &destination);
		CUI_EXPECT_TRUE(destinationReference.Get()
			== destination.FindControlByDesignId<Button>(17));
		CUI_EXPECT_EQ(std::wstring(L"Second"), destinationReference->GetDisplayText());
		CUI_EXPECT_FALSE(static_cast<bool>(replacementDocumentReference));
		CUI_EXPECT_TRUE(replacementReference.Get() == nullptr);
	});

	runner.Add("Visual presentation revisions keep content geometry and composition independent", []
	{
		Label visual; ConfigureTestControl(visual, L"revision probe", 0, 0);
		const auto initial = visual.GetPresentationRevisions();
		visual.InvalidateVisual();
		const auto content = visual.GetPresentationRevisions();
		CUI_EXPECT_TRUE(content.Content > initial.Content);
		CUI_EXPECT_EQ(initial.Geometry, content.Geometry);
		CUI_EXPECT_EQ(initial.Composition, content.Composition);

		cui::drawing::Transform transform;
		cui::drawing::TransformOperation translate;
		translate.Kind = cui::drawing::TransformKind::Translate;
		translate.X = 8.0f;
		translate.Y = 4.0f;
		transform.Operations.push_back(translate);
		visual.SetRenderTransform(transform);
		const auto transformed = visual.GetPresentationRevisions();
		CUI_EXPECT_EQ(content.Content, transformed.Content);
		CUI_EXPECT_TRUE(transformed.Geometry > content.Geometry);
		CUI_EXPECT_EQ(content.Composition, transformed.Composition);

		visual.Arrange(cui::core::Rect{ 12.0f, 18.0f, 160.0f, 32.0f });
		const auto arranged = visual.GetPresentationRevisions();
		CUI_EXPECT_EQ(transformed.Content, arranged.Content);
		CUI_EXPECT_TRUE(arranged.Geometry > transformed.Geometry);
		CUI_EXPECT_EQ(transformed.Composition, arranged.Composition);

		visual.InvalidateComposition();
		const auto composed = visual.GetPresentationRevisions();
		CUI_EXPECT_EQ(arranged.Content, composed.Content);
		CUI_EXPECT_EQ(arranged.Geometry, composed.Geometry);
		CUI_EXPECT_TRUE(composed.Composition > arranged.Composition);
	});

	runner.Add("Input staging shares one tunnel bubble route with handled class semantics", []
	{
		Panel outer;
		auto middleOwner = MakeTestControl<Panel>();
		auto sourceOwner = MakeTestControl<Button>(L"source", 0, 0);
		auto* middle = middleOwner.get();
		auto* source = sourceOwner.get();
		outer.AddOwned(std::move(middleOwner));
		middle->AddOwned(std::move(sourceOwner));
		const auto frameworkOuterMouseDownHandlers =
			outer.OnMouseDown.Count();

		std::vector<std::wstring> route;
		auto outerPreview = outer.OnPreviewMouseDown.Subscribe(
			[&](Control* sender, MouseEventArgs& args)
			{
				CUI_EXPECT_TRUE(sender == &outer);
				CUI_EXPECT_TRUE(args.CurrentTarget == &outer);
				CUI_EXPECT_TRUE(args.OriginalSource == source);
				route.push_back(L"preview.outer");
			});
		auto middlePreview = middle->OnPreviewMouseDown.Subscribe(
			[&](Control*, MouseEventArgs& args)
			{
				CUI_EXPECT_TRUE(args.CurrentTarget == middle);
				route.push_back(L"preview.middle");
			});
		auto sourcePreview = source->OnPreviewMouseDown.Subscribe(
			[&](Control*, MouseEventArgs& args)
			{
				CUI_EXPECT_EQ(RoutedEventStage::Preview, args.Stage);
				route.push_back(L"preview.source");
			});
		auto classHandler = RoutedEventManager::RegisterClassHandler(
			UIClass::UI_Button, RoutedEventId::MouseDown,
			[&](Control* sender, RoutedEventArgs& args)
			{
				CUI_EXPECT_TRUE(sender == source);
				CUI_EXPECT_TRUE(args.CurrentTarget == source);
				route.push_back(L"class.source");
			});
		auto sourceBubble = source->OnMouseDown.Subscribe(
			[&](Control*, MouseEventArgs& args)
			{
				CUI_EXPECT_EQ(RoutedEventStage::Bubble, args.Stage);
				route.push_back(L"bubble.source");
				args.Handled = true;
			});
		auto skippedMiddle = middle->OnMouseDown.Subscribe(
			[&](Control*, MouseEventArgs&)
			{ route.push_back(L"bubble.middle.unexpected"); });
		auto skippedOuter = outer.OnMouseDown.Subscribe(
			[&](Control*, MouseEventArgs&)
			{ route.push_back(L"bubble.outer.unexpected"); });
		auto handledOuter = outer.OnMouseDown.Subscribe(
			[&](Control*, MouseEventArgs& args)
			{
				CUI_EXPECT_TRUE(args.Handled);
				route.push_back(L"bubble.outer.handledToo");
			}, true);

		InputManager input;
		MouseEventArgs preview(
			MouseButton::Left, MouseButtonState::Pressed,
			1, 4, 5, 0);
		MouseEventArgs bubble(
			MouseButton::Left, MouseButtonState::Pressed,
			1, 4, 5, 0);
		{
			InputManager::StagingScope staging(
				input, source, RoutedEventId::MouseDown, 4.0f, 5.0f);
			staging.Preview(preview);
			source->OnMouseDown(source, bubble);
			staging.Complete(bubble);
			CUI_EXPECT_TRUE(staging.Handled());
		}
		CUI_EXPECT_EQ((std::vector<std::wstring>{
			L"preview.outer", L"preview.middle", L"preview.source",
			L"class.source", L"bubble.source",
			L"bubble.outer.handledToo" }), route);
		CUI_EXPECT_TRUE(bubble.Handled);
		CUI_EXPECT_TRUE(bubble.OriginalSource == source);
		CUI_EXPECT_TRUE(bubble.Source == source);
		CUI_EXPECT_TRUE(bubble.CurrentTarget == nullptr);
		const auto statistics = input.Statistics();
		CUI_EXPECT_EQ(1ULL, statistics.RawReports);
		CUI_EXPECT_EQ(1ULL, statistics.CompletedReports);
		CUI_EXPECT_EQ(1ULL, statistics.PreviewRoutes);
		CUI_EXPECT_EQ(1ULL, statistics.BubbleRoutes);
		CUI_EXPECT_TRUE(statistics.HandlersSkippedAfterHandled >= 2);
		CUI_EXPECT_EQ(3ULL, statistics.MaxRouteDepth);

		handledOuter.Disconnect();
		CUI_EXPECT_EQ(frameworkOuterMouseDownHandlers + 1,
			outer.OnMouseDown.Count());
	});

	runner.Add("AllowDrop inheritance routes one DragEventArgs preview bubble pair", []
	{
		Panel outer;
		auto middleOwner = MakeTestControl<Panel>();
		auto sourceOwner = MakeTestControl<Button>(L"drop source", 0, 0);
		auto* middle = middleOwner.get();
		auto* source = sourceOwner.get();
		outer.AddOwned(std::move(middleOwner));
		middle->AddOwned(std::move(sourceOwner));
		CUI_EXPECT_TRUE(outer.TrySetPropertyValue(
			L"AllowDrop", BindingValue(true)));
		CUI_EXPECT_TRUE(outer.AllowDrop);
		CUI_EXPECT_TRUE(middle->AllowDrop);
		CUI_EXPECT_TRUE(source->AllowDrop);
		CUI_EXPECT_EQ(DependencyPropertyValueSource::Inherited,
			source->GetPropertyValueSource(L"AllowDrop"));

		auto data = std::make_shared<const DragDataObject>(
			std::vector<std::wstring>{ L"image.png" },
			std::optional<std::wstring>{ L"drag text" });
		std::vector<std::wstring> route;
		auto outerPreview = outer.OnPreviewDrop.Subscribe(
			[&](Control*, DragEventArgs& args)
			{
				CUI_EXPECT_TRUE(args.Data == data);
				CUI_EXPECT_TRUE(args.OriginalSource == source);
				CUI_EXPECT_EQ(RoutedEventStage::Preview, args.Stage);
				route.push_back(L"preview.outer");
			});
		auto middlePreview = middle->OnPreviewDrop.Subscribe(
			[&](Control*, DragEventArgs&)
			{ route.push_back(L"preview.middle"); });
		auto sourcePreview = source->OnPreviewDrop.Subscribe(
			[&](Control*, DragEventArgs&)
			{ route.push_back(L"preview.source"); });
		auto sourceDrop = source->OnDrop.Subscribe(
			[&](Control*, DragEventArgs& args)
			{
				CUI_EXPECT_EQ(DragDropEffects::Copy,
					args.AllowedEffects & DragDropEffects::Copy);
				args.Effects = DragDropEffects::Copy;
				args.Handled = true;
				route.push_back(L"bubble.source");
			});
		auto skippedMiddle = middle->OnDrop.Subscribe(
			[&](Control*, DragEventArgs&)
			{ route.push_back(L"bubble.middle.unexpected"); });
		auto handledOuter = outer.OnDrop.Subscribe(
			[&](Control*, DragEventArgs& args)
			{
				CUI_EXPECT_TRUE(args.Handled);
				route.push_back(L"bubble.outer.handledToo");
			}, true);

		DragEventArgs args(
			data, DragDropKeyStates::ControlKey,
			DragDropEffects::Copy | DragDropEffects::Move,
			24.0f, 36.0f);
		source->OnDrop(source, args);
		CUI_EXPECT_EQ((std::vector<std::wstring>{
			L"preview.outer", L"preview.middle", L"preview.source",
			L"bubble.source", L"bubble.outer.handledToo" }), route);
		CUI_EXPECT_TRUE(args.Handled);
		CUI_EXPECT_EQ(DragDropEffects::Copy, args.Effects);
		CUI_EXPECT_TRUE(args.Data->HasFiles());
		CUI_EXPECT_TRUE(args.Data->HasText());
		CUI_EXPECT_TRUE(args.CurrentTarget == nullptr);
		CUI_EXPECT_EQ(RoutedEventId::Drop, args.EventId);
	});

